#[test]
fn sprint_parent_epic_scope_preserves_explicit_descendants_and_audits_detach() {
    let fixture = Fixture::new("sprint-parent-scope");
    fixture.ok_json(&fixture.main, &["init", "--name", "SPRINT-SCOPE", "--json"]);
    sprint_fixture_new(&fixture, "sp-release", "2.0.0");
    sprint_fixture_new(&fixture, "sp-other", "2.1.0");
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "Release epic",
            "--id",
            "e-release",
            "--type",
            "epic",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "Release story",
            "--id",
            "s-release",
            "--type",
            "story",
            "--parent",
            "e-release",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "Inherited task",
            "--id",
            "t-inherited",
            "--parent",
            "s-release",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "Already planned elsewhere",
            "--id",
            "t-other",
            "--parent",
            "s-release",
            "--sprint",
            "sp-other",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-release",
            "--body",
            "Ship release 2.0
Epic subtree is the scope",
            "--parent-epic",
            "e-release",
            "--as",
            "operator",
            "--json",
        ],
    );

    let release = fixture.ok_json(&fixture.main, &["sprint", "show", "sp-release", "--json"]);
    let release_ids = release["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .map(|task| task["id"].as_str().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(release_ids, ["e-release", "s-release", "t-inherited"]);
    let other = fixture.ok_json(&fixture.main, &["sprint", "show", "sp-other", "--json"]);
    assert_eq!(other["tasks"][0]["id"], "t-other");

    for task_id in ["e-release", "s-release", "t-inherited"] {
        let events = fixture.ok_json(
            &fixture.main,
            &[
                "events",
                "--task",
                task_id,
                "--kind",
                "task_sprint_changed",
                "--json",
            ],
        );
        assert_eq!(
            events[0]["payload"]["oldSprintID"],
            Value::Null,
            "{task_id}: {events}"
        );
        assert_eq!(
            events[0]["payload"]["newSprintID"], "sp-release",
            "{task_id}: {events}"
        );
    }

    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "update",
            "t-inherited",
            "--as",
            "operator",
            "--clear-sprint",
            "--json",
        ],
    );
    let detached = fixture.ok_json(
        &fixture.main,
        &[
            "events",
            "--task",
            "t-inherited",
            "--kind",
            "task_sprint_changed",
            "--json",
        ],
    );
    assert_eq!(detached[0]["payload"]["oldSprintID"], "sp-release");
    assert_eq!(detached[0]["payload"]["newSprintID"], Value::Null);
    assert_eq!(
        fixture.ok_json(&fixture.main, &["sprint", "show", "sp-other", "--json"])["tasks"][0]["id"],
        "t-other"
    );
    assert_eq!(
        fixture.ok_json(&fixture.main, &["audit", "verify", "--json"])["healthy"],
        true
    );
}

#[test]
fn sprint_claim_boundary_filters_scheduler_and_records_only_explicit_overrides() {
    let fixture = Fixture::new("sprint-claim-boundary");
    fixture.ok_json(
        &fixture.main,
        &["init", "--name", "SPRINT-CLAIMS", "--json"],
    );
    sprint_fixture_new(&fixture, "sp-current-boundary", "3.0.0");
    sprint_fixture_new(&fixture, "sp-other-boundary", "3.1.0");
    for (id, sprint) in [
        ("t-current-boundary", Some("sp-current-boundary")),
        ("t-other-boundary", Some("sp-other-boundary")),
        ("t-unattached-boundary", None),
    ] {
        let mut args = vec!["task", "add", id, "--id", id];
        if let Some(sprint) = sprint {
            args.extend(["--sprint", sprint]);
        }
        args.push("--json");
        fixture.ok_json(&fixture.main, &args);
    }
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-current-boundary",
            "--body",
            "Ship current scope
Only attached work is claimable",
            "--candidate",
            "t-current-boundary",
            "--as",
            "operator",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "start",
            "sp-current-boundary",
            "--as",
            "operator",
            "--json",
        ],
    );

    let candidates = fixture.ok_json(
        &fixture.main,
        &[
            "claim",
            "--candidates",
            "--as",
            "candidate-reader",
            "--json",
        ],
    );
    assert_eq!(candidates.as_array().unwrap().len(), 1, "{candidates}");
    assert_eq!(candidates[0]["id"], "t-current-boundary");
    let next = fixture.ok_json(
        &fixture.main,
        &["claim", "--next", "--as", "next-worker", "--json"],
    );
    assert_eq!(next["taskID"], "t-current-boundary");
    let implicit_event = fixture.ok_json(
        &fixture.main,
        &[
            "events",
            "--task",
            "t-current-boundary",
            "--kind",
            "task_claimed",
            "--json",
        ],
    );
    assert!(
        implicit_event[0]["payload"].get("sprintOverride").is_none(),
        "an implicit current-sprint selection was falsely recorded as an override: {implicit_event}"
    );

    let refused = fixture.run(
        &fixture.main,
        &[
            "claim",
            "t-other-boundary",
            "--as",
            "direct-worker",
            "--json",
        ],
    );
    assert!(refusal_object(&refused).contains("not in sprint sp-current-boundary"));
    let named = fixture.ok_json(
        &fixture.main,
        &[
            "claim",
            "t-other-boundary",
            "--as",
            "named-worker",
            "--sprint",
            "sp-other-boundary",
            "--json",
        ],
    );
    assert_eq!(named["taskID"], "t-other-boundary");
    let any = fixture.ok_json(
        &fixture.main,
        &[
            "claim",
            "t-unattached-boundary",
            "--as",
            "any-worker",
            "--any-sprint",
            "--json",
        ],
    );
    assert_eq!(any["taskID"], "t-unattached-boundary");
    let named_event = fixture.ok_json(
        &fixture.main,
        &[
            "events",
            "--task",
            "t-other-boundary",
            "--kind",
            "task_claimed",
            "--json",
        ],
    );
    assert_eq!(
        named_event[0]["payload"]["sprintOverride"],
        "sp-other-boundary"
    );
    let any_event = fixture.ok_json(
        &fixture.main,
        &[
            "events",
            "--task",
            "t-unattached-boundary",
            "--kind",
            "task_claimed",
            "--json",
        ],
    );
    assert_eq!(any_event[0]["payload"]["sprintOverride"], "any");

    let legacy = Fixture::new("claim-without-current-sprint");
    legacy.ok_json(
        &legacy.main,
        &["init", "--name", "NO-CURRENT-SPRINT", "--json"],
    );
    legacy.ok_json(
        &legacy.main,
        &[
            "task",
            "add",
            "Legacy claim",
            "--id",
            "t-legacy-claim",
            "--json",
        ],
    );
    let legacy_candidates = legacy.ok_json(
        &legacy.main,
        &["claim", "--candidates", "--as", "legacy-worker", "--json"],
    );
    assert_eq!(legacy_candidates[0]["id"], "t-legacy-claim");
    legacy.ok_json(
        &legacy.main,
        &["claim", "--next", "--as", "legacy-worker", "--json"],
    );
    let legacy_event = legacy.ok_json(
        &legacy.main,
        &[
            "events",
            "--task",
            "t-legacy-claim",
            "--kind",
            "task_claimed",
            "--json",
        ],
    );
    assert!(
        legacy_event[0]["payload"].get("sprintOverride").is_none(),
        "{legacy_event}"
    );
}

#[test]
fn sprint_current_boundary_requires_deliberate_scope_and_enriches_only_attached_context() {
    let fixture = Fixture::new("sprint-context-boundary");
    fixture.ok_json(
        &fixture.main,
        &["init", "--name", "SPRINT-CONTEXT", "--json"],
    );
    sprint_fixture_new(&fixture, "sp-context-current", "4.0.0");
    sprint_fixture_new(&fixture, "sp-context-next", "4.1.0");
    fixture.ok_json(
        &fixture.main,
        &["task", "add", "Attached", "--id", "t-context-in", "--json"],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "Unattached",
            "--id",
            "t-context-out",
            "--json",
        ],
    );

    let missing_scope = fixture.run(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-context-next",
            "--body",
            "Next goal
Scope must be deliberate",
            "--as",
            "operator",
            "--json",
        ],
    );
    assert!(refusal_object(&missing_scope).contains(
        "requires --candidate, --parent-epic, existing explicit scope, or --empty-scope"
    ));
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-context-current",
            "--body",
            "Exact context goal
Attached context names the release",
            "--candidate",
            "t-context-in",
            "--as",
            "operator",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "start",
            "sp-context-current",
            "--as",
            "operator",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-context-next",
            "--body",
            "Next goal
Deliberately empty",
            "--empty-scope",
            "--as",
            "operator",
            "--json",
        ],
    );
    let second_start = fixture.run(
        &fixture.main,
        &[
            "sprint",
            "start",
            "sp-context-next",
            "--as",
            "operator",
            "--json",
        ],
    );
    let second_error = refusal_object(&second_start);
    assert!(
        second_error.contains("sp-context-current") && second_error.contains("sp-context-next"),
        "{second_error}"
    );

    let context = fixture.ok_json(&fixture.main, &["context", "t-context-in", "--json"]);
    assert_eq!(context["sprint"]["sprintID"], "sp-context-current");
    assert_eq!(context["sprint"]["targetVersion"], "4.0.0");
    assert_eq!(context["sprint"]["goal"], "Exact context goal");
    let text = fixture.run(&fixture.main, &["context", "t-context-in"]);
    assert!(text.status.success());
    let text = String::from_utf8_lossy(&text.stdout);
    assert!(
        text.contains(r#"sp-context-current "sp-context-current" v4.0.0 · current"#),
        "{text}"
    );
    assert!(text.contains("Goal: Exact context goal"), "{text}");

    let unattached = fixture.ok_json(&fixture.main, &["context", "t-context-out", "--json"]);
    assert!(unattached.get("sprint").is_none(), "{unattached}");
    let unattached_text = fixture.run(&fixture.main, &["context", "t-context-out"]);
    assert!(unattached_text.status.success());
    assert!(!String::from_utf8_lossy(&unattached_text.stdout).contains("## Sprint"));
}

#[test]
fn sprint_close_rejects_every_unqualified_proof_and_durably_records_carry() {
    let fixture = Fixture::new("sprint-close-gates");
    fixture.ok_json(&fixture.main, &["init", "--name", "SPRINT-CLOSE", "--json"]);
    sprint_fixture_new(&fixture, "sp-close-current", "5.0.0");
    sprint_fixture_new(&fixture, "sp-close-carry", "5.1.0");
    fixture.ok_json(
        &fixture.main,
        &["task", "add", "Unfinished", "--id", "t-carry", "--json"],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-close-current",
            "--body",
            "Ship exact 5.0.0
Only verified serving closes",
            "--candidate",
            "t-carry",
            "--as",
            "operator",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "start",
            "sp-close-current",
            "--as",
            "operator",
            "--json",
        ],
    );

    let absent = fixture.run(
        &fixture.main,
        &[
            "sprint",
            "close",
            "sp-close-current",
            "--as",
            "operator",
            "--json",
        ],
    );
    assert!(refusal_object(&absent).contains("requires --deployment"));

    let failed = sprint_fixture_deployment(
        &fixture,
        "sp-close-current",
        "5.0.0",
        "failed",
        "verification",
    );
    let failed_close = fixture.run(
        &fixture.main,
        &[
            "sprint",
            "close",
            "sp-close-current",
            "--deployment",
            &failed,
            "--as",
            "operator",
            "--json",
        ],
    );
    assert!(refusal_object(&failed_close).contains("failed (verification)"));

    let build = fixture.ok_json(
        &fixture.main,
        &[
            "deploy",
            "start",
            "--repo",
            "fixture/local",
            "--commit",
            "cccccccccccccccccccccccccccccccccccccccc",
            "--tier",
            "@_bdt",
            "--environment",
            "local-test",
            "--host",
            "geoywsMBP",
            "--url",
            "https://fixture.invalid",
            "--sprint",
            "sp-close-current",
            "--as",
            "operator",
            "--json",
        ],
    );
    let build_id = build["id"].as_str().unwrap();
    let build_token = build["capabilityToken"].as_str().unwrap();
    let non_verification = fixture.run(
        &fixture.main,
        &[
            "deploy",
            "finish",
            build_id,
            "--token",
            build_token,
            "--result",
            "succeeded",
            "--phase",
            "build",
            "--receipt",
            "simulated local test data; no live claim or external deployment",
            "--as",
            "operator",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&non_verification),
        "a succeeded deployment requires --phase verification"
    );
    assert_eq!(
        fixture.ok_json(&fixture.main, &["deploy", "show", build_id, "--json"])["status"],
        "started",
        "the refused non-verification result finalized the deployment"
    );
    let other = sprint_fixture_deployment(
        &fixture,
        "sp-close-carry",
        "5.1.0",
        "succeeded",
        "verification",
    );
    let other_close = fixture.run(
        &fixture.main,
        &[
            "sprint",
            "close",
            "sp-close-current",
            "--deployment",
            &other,
            "--as",
            "operator",
            "--json",
        ],
    );
    assert!(refusal_object(&other_close).contains("bound to this sprint and served version 5.0.0"));

    let proof = sprint_fixture_deployment(
        &fixture,
        "sp-close-current",
        "5.0.0",
        "succeeded",
        "verification",
    );
    let unnamed_note = fixture.run(
        &fixture.main,
        &[
            "sprint",
            "close",
            "sp-close-current",
            "--deployment",
            &proof,
            "--carry-to",
            "sp-close-carry",
            "--as",
            "operator",
            "--json",
        ],
    );
    assert!(refusal_object(&unnamed_note).contains("carry-over note"));
    let note = "Carry t-carry after simulated local verification";
    let closed = fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "close",
            "sp-close-current",
            "--deployment",
            &proof,
            "--carry-to",
            "sp-close-carry",
            "--carry-note",
            note,
            "--as",
            "operator",
            "--json",
        ],
    );
    assert_eq!(closed["status"], "closed");
    assert_eq!(closed["closedByDeployment"], proof);
    let destination = fixture.ok_json(
        &fixture.main,
        &["sprint", "show", "sp-close-carry", "--json"],
    );
    assert_eq!(destination["tasks"][0]["id"], "t-carry");
    assert_eq!(destination["tasks"][0]["status"], "todo");
    let carry_event = fixture.ok_json(
        &fixture.main,
        &[
            "events",
            "--task",
            "t-carry",
            "--kind",
            "task_sprint_changed",
            "--json",
        ],
    );
    assert_eq!(carry_event[0]["payload"]["oldSprintID"], "sp-close-current");
    assert_eq!(carry_event[0]["payload"]["newSprintID"], "sp-close-carry");
    assert_eq!(carry_event[0]["payload"]["carryNote"], note);
    let close_event = fixture.ok_json(
        &fixture.main,
        &["events", "--kind", "sprint_closed", "--json"],
    );
    assert_eq!(close_event[0]["payload"]["sprintID"], "sp-close-current");
    assert_eq!(close_event[0]["payload"]["deploymentID"], proof);
    assert_eq!(close_event[0]["payload"]["targetVersion"], "5.0.0");
    assert_eq!(
        fixture.ok_json(&fixture.main, &["audit", "verify", "--json"])["healthy"],
        true
    );
}

/// A long body: enough lines that the region holding it has to scroll on any
/// screen, so "the body is the scroller" is measured rather than assumed.
fn long_body(lead: &str) -> String {
    let mut body = String::from(lead);
    for line in 0..70 {
        body.push_str(&format!(
            "\n\nLine {line:02} of the long form, written out at the length a raiser writes it, \
             so that the card's own body is taller than the region the deck gives it."
        ));
    }
    body
}

/// Three open items on one board, each a full card with the same three
/// choices, so a deck has a queue to walk.
fn deck_fixture(label: &str, board: &str) -> (Fixture, Vec<String>) {
    let fixture = Fixture::new(label);
    fixture.ok_json(&fixture.main, &["init", "--name", board, "--json"]);
    let mut ids = Vec::new();
    for (index, priority) in ["0", "1", "2"].iter().enumerate() {
        let item = raise_carded(
            &fixture,
            &long_body(&format!("Card {index} of the deck fixture.")),
            "codex@driver",
            &card_args(&["--kind", "blocking", "--priority", priority], &CARD),
        );
        ids.push(item["id"].as_str().expect("raised id").to_owned());
    }
    (fixture, ids)
}

/// What the deck measures to, on one viewport.
const DECK_MEASURE: &str = r#"(() => {
  const cards = [...document.querySelectorAll('__CARD__')];
  const shown = cards.filter(card => card.checkVisibility());
  const card = document.querySelector('__CURRENT_CARD__');
  const body = card.querySelector('__FULL__ .body');
  const decide = card.querySelector('__DECIDE__');
  const heading = card.querySelector('h2');
  const context = card.querySelector('p.context');
  const round = value => Math.round(value);
  return JSON.stringify({
    width: innerWidth,
    height: innerHeight,
    shown: shown.length,
    current: card.dataset.item,
    pageScrollHeight: document.scrollingElement.scrollHeight,
    pageScrollWidth: document.documentElement.scrollWidth,
    bodyScrollHeight: body.scrollHeight,
    bodyClientHeight: body.clientHeight,
    decideBottom: round(decide.getBoundingClientRect().bottom),
    decideHeight: round(decide.getBoundingClientRect().height),
    headingTop: round(heading.getBoundingClientRect().top),
    contextTop: round(context.getBoundingClientRect().top),
    contextBottom: round(context.getBoundingClientRect().bottom),
    contextScrollHeight: context.scrollHeight,
    contextClientHeight: context.clientHeight,
    contextOverflow: getComputedStyle(context).overflowY,
    cardTop: round(card.getBoundingClientRect().top),
    cardBottom: round(card.getBoundingClientRect().bottom),
    cardScrollHeight: card.scrollHeight,
    cardClientHeight: card.clientHeight,
    aside: document.querySelector('__SIDE__').checkVisibility(),
    toggle: document.querySelector('__HISTORY_TOGGLE__').checkVisibility(),
  });
})()"#;

/// One card at a time, the long form scrolling inside its own region, and
/// the card's own column the one thing that takes the overflow (George,
/// 2026-09-17: "we are looking at one item at a time, with the scrollable
/// being only the body of the text and the 4 questions and the optional note
/// wisely having a bit of space at the bottom of the screen in a sticky
/// way").
///
/// Superseded 2026-09-18: this case used to require the answer panel's
/// bottom edge to be inside the viewport, which the panel bought by capping
/// itself at three fifths of the card and scrolling its own answers -- the
/// nested scroller that put the note off a 390x844 phone. The panel is a
/// block at the foot of the card's column now, so what is asserted here is
/// that it is REACHABLE inside that column; that scrolling there actually
/// lands the note and the answers on screen is
/// `the_deck_answers_stack_and_the_note_is_reached_by_one_scroller_at_three_widths_in_real_chrome`.
///
/// Measured on three screens, because this is a layout claim and a layout
/// claim on one viewport is an anecdote: a phone, a tablet and a laptop
/// window. On each one the page itself must not scroll in either direction,
/// the long form must have more to show than it can fit, the answers must be
/// inside the card's own scroll extent, and the question must not have been
/// pushed off the top of the screen.
///
/// The side history is the other half: a column of its own where there is
/// room for one, and behind a button where there is not.
#[test]
fn the_deck_shows_one_card_and_only_its_body_scrolls_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, ids) = deck_fixture("serve-deck-scroll", "DECKSCROLL");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);

    for (width, height) in [(390, 844), (820, 1180), (1280, 800)] {
        set_viewport(&tab, width, height);
        // A resize is a relayout, and the measurement has to be of the
        // relaid-out page rather than of the one before it.
        wait_for_js_true(&tab, &format!("innerWidth === {width}"));
        let measured: Value = serde_json::from_str(
            js_value(&tab, DECK_MEASURE)
                .as_str()
                .expect("the deck measurement"),
        )
        .expect("the deck measurement parses");
        eprintln!("deck at {width}x{height}: {measured}");
        let number = |key: &str| measured[key].as_i64().unwrap_or_else(|| panic!("{key}"));
        assert_eq!(measured["shown"], 1, "{measured}");
        assert_eq!(measured["current"], ids[0].as_str(), "{measured}");
        assert!(
            number("pageScrollHeight") <= i64::from(height),
            "the page itself scrolls at {width}x{height}: {measured}"
        );
        assert!(
            number("pageScrollWidth") <= i64::from(width),
            "the page overflows sideways at {width}x{height}: {measured}"
        );
        assert!(
            number("bodyScrollHeight") > number("bodyClientHeight"),
            "the long form is not the scroller at {width}x{height}: {measured}"
        );
        // The panel's foot IS the foot of the card's scroll content, so this
        // is an equality with a pixel of slack: every rect here is rounded
        // to whole pixels and two of them are subtracted.
        assert!(
            number("decideBottom") - number("cardTop") <= number("cardScrollHeight") + 1,
            "the answers are outside the card's own scroll extent, so no amount of \
             scrolling reaches them at {width}x{height}: {measured}"
        );
        assert!(
            number("decideHeight") > 0,
            "the answers have no height at {width}x{height}: {measured}"
        );
        assert!(
            number("headingTop") >= 0,
            "the question is above the top of the screen at {width}x{height}: {measured}"
        );
        // The raiser's context is INSIDE what scrolls, above the long form,
        // and it is never a clipped region of its own: George's screenshots
        // showed it cut off mid-sentence, which is the one thing a card must
        // never do to the paragraph that says what the question means.
        assert!(
            number("contextTop") >= number("cardTop") - 1
                && number("contextBottom") <= number("cardBottom") + 1,
            "the context is outside the card's own scroll region at {width}x{height}: {measured}"
        );
        assert!(
            number("contextScrollHeight") <= number("contextClientHeight") + 1,
            "the context is clipped mid-sentence at {width}x{height}: {measured}"
        );
        assert_eq!(
            measured["contextOverflow"], "visible",
            "the context clips what it cannot fit at {width}x{height}: {measured}"
        );
        assert_eq!(
            measured["aside"],
            Value::Bool(width >= 900),
            "the side history is a column only where there is room for one: {measured}"
        );
        assert_eq!(
            measured["toggle"],
            Value::Bool(width < 900),
            "the side history's button is there only when the column is not: {measured}"
        );
    }

    // Back on the phone, the menu is one button and one key, and Escape puts
    // it away: eight destinations across the top is what the deck reclaimed.
    set_viewport(&tab, 390, 844);
    wait_for_js_true(&tab, "innerWidth === 390");
    tab.press_key("m").expect("press m");
    wait_for_js_true(&tab, "!document.querySelector('[data-drawer]').hidden");
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('[data-menu]').getAttribute('aria-expanded')"
        ),
        "true"
    );
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('[data-nav=all]').getAttribute('href')"
        ),
        "/all",
        "the menu has to hold the plain list, which is where the whole queue is"
    );
    tab.press_key("Escape").expect("press Escape");
    wait_for_js_true(&tab, "document.querySelector('[data-drawer]').hidden");
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('[data-backdrop]').hidden \
             && document.querySelector('[data-menu]').getAttribute('aria-expanded') === 'false'"
        ),
        Value::Bool(true),
        "the menu closed without taking its backdrop with it"
    );
    // And `/all` is reached the way every other destination is, since
    // `t-bf255880` wave 2 mounted it: the drawer link routes in place. The
    // marker is on the window the deck was rendered in, so it survives a
    // route change and cannot survive a new document.
    assert_eq!(js_value(&tab, "window.__sameDocument = true"), true);
    click_routing(&tab, "[data-nav=all]", ui::CARD, "/all", "All open nav");
    assert_eq!(
        js_value(&tab, "window.__sameDocument === true"),
        Value::Bool(true),
        "the drawer's `/all` link asked the server for a new document"
    );
}

/// What one card measures to once the answers stack and the card's own
/// column is the one scroller (2026-09-18).
///
/// The headline's line count is its height over its computed `line-height`
/// and not `getClientRects().length`: `h2` is a block, so it has exactly one
/// client rect however many lines of text are inside it.
const DECK_STACK_MEASURE: &str = r#"(() => {
  const card = document.querySelector('__CURRENT_CARD__');
  const panel = card.querySelector('__DECK_PANEL__');
  const answers = card.querySelector('__DECK_ANSWERS__');
  const choices = [...card.querySelectorAll('__DECK_CHOICES__')];
  const note = card.querySelector('__DECK_NOTE__');
  const keys = document.querySelector('__DECK_KEYS__');
  const body = card.querySelector('__DECK_BODY__');
  const lead = card.querySelector('fieldset.recommended __DECK_CHOICES__');
  const context = card.querySelector('p.context');
  const heading = card.querySelector('h2');
  const pill = card.querySelector('__DECK_PRIORITY__');
  // What, if anything, has text in the band between the foot of the long
  // form and the head of the answer panel. Ancestors of either span the
  // band by definition and their descendants are inside one of them, so the
  // only nodes left are the ones that really sit in the gap -- which is
  // where the priority pill used to sit, directly under text dissolving
  // into the fade.
  const bandOccupants = () => {
    const from = body.getBoundingClientRect().bottom;
    const to = panel.getBoundingClientRect().top;
    return [...card.querySelectorAll('*')]
      .filter(node => node !== body && node !== panel
        && !node.contains(body) && !node.contains(panel)
        && !body.contains(node) && !panel.contains(node)
        && (node.textContent || '').trim().length > 0
        && node.checkVisibility())
      .map(node => ({node, box: node.getBoundingClientRect()}))
      .filter(({box}) => box.height > 0 && box.bottom > from + 0.5 && box.top < to - 0.5)
      .map(({node}) => `${node.tagName.toLowerCase()}.${node.className}=`
        + (node.textContent || '').trim().slice(0, 40));
  };
  const round = value => Math.round(value);
  const rect = el => {
    const box = el.getBoundingClientRect();
    return {top: round(box.top), bottom: round(box.bottom), left: round(box.left),
            right: round(box.right), width: round(box.width), height: round(box.height)};
  };
  const style = getComputedStyle(heading);
  return JSON.stringify({
    width: innerWidth,
    height: innerHeight,
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
    cardScrollTop: round(card.scrollTop),
    cardScrollHeight: card.scrollHeight,
    cardClientHeight: card.clientHeight,
    panel: rect(panel),
    panelScrollHeight: panel.scrollHeight,
    panelClientHeight: panel.clientHeight,
    answers: rect(answers),
    choices: choices.map(choice => Object.assign({id: choice.dataset.testid}, rect(choice))),
    lead: rect(lead),
    contextInBody: Boolean(context) && context.parentElement === body,
    note: rect(note),
    pill: rect(pill),
    band: bandOccupants(),
    keys: rect(keys),
    body: Object.assign(rect(body),
      {scrollHeight: body.scrollHeight, clientHeight: body.clientHeight}),
    heading: rect(heading),
    headingLines: Math.round(heading.getBoundingClientRect().height
      / parseFloat(style.lineHeight)),
    headingFontSize: style.fontSize,
  });
})()"#;

/// Scroll the current card's own column to its end and report where it
/// landed, which is the one gesture that reaches the note now.
const SCROLL_CARD_TO_END: &str = "(() => { \
     const card = document.querySelector('__CURRENT_CARD__'); \
     card.scrollTo(0, card.scrollHeight); return Math.round(card.scrollTop); })()";

/// Put the current card's column back to its top, which is where the deck
/// opens a card: the sweep scrolls it to its end at every width, so the next
/// width has to start from the same place a reader does.
const SCROLL_CARD_TO_TOP: &str = "(() => { \
     const card = document.querySelector('__CURRENT_CARD__'); \
     card.scrollTo(0, 0); return Math.round(card.scrollTop); })()";

/// WEB-47, WEB-35, WEB-02 as superseded on 2026-09-18 — one answer per row,
/// one scroller, and the note reached by it.
///
/// George, 2026-09-18, on the served deck: "it's up but it's squished and
/// not mobile responsive"; "the web version looks mushed up ... (iPad has it
/// squished up)". What was measured then: the answers were a two-column grid
/// of 177px buttons with three- and four-line labels on a 390px phone, and
/// the panel was capped at three fifths of the card and scrolled its own
/// content, which put the note field at y=961 on an 844px screen with
/// nothing to say it was there and cut the fourth answer at the cap.
///
/// So this case measures the whole claim on the three screens George decides
/// on: every answer on a row of its own at the card's full content width,
/// nothing scrolling inside the panel, the long form still scrolling inside
/// its own region and never reaching over the answers, the keyboard line on
/// screen throughout, the RECOMMENDED answer on the screen the card opens
/// on, and the note landing fully inside the viewport and above the keyboard
/// line once the card's own column is scrolled to its end.
///
/// Two cards, because a layout claim proved on the short one is a claim
/// about the short one: the shipped fixture card (133-char question, 452 of
/// context, three answers) and [`LONG_CARD`], which is the product's own
/// bounds — 160-char question, 793 of context, four answers. The long one is
/// why the raiser's context moved inside the body region: as a free block it
/// put the recommendation two scrolls down on a phone.
#[test]
fn the_deck_answers_stack_and_the_note_is_reached_by_one_scroller_at_three_widths_in_real_chrome() {
    let desk = deck_stack_desk("serve-deck-stack", "DECKSTACK");
    let num = |value: &Value| {
        value
            .as_i64()
            .unwrap_or_else(|| panic!("a measured number, not {value}"))
    };
    let current_item = || {
        js_value(
            &desk.tab,
            "document.querySelector('__CURRENT_CARD__').dataset.item",
        )
        .as_str()
        .expect("the current card's item")
        .to_owned()
    };
    let mut seen: Vec<String> = Vec::new();
    for card in 0..2 {
        let item = current_item();
        eprintln!("the stacked deck is showing {item}");
        // The deck opens a card at its top, and that is not something the
        // sweep below arranged: this card has never been scrolled.
        let opened = measure(
            &desk.tab,
            DECK_STACK_MEASURE,
            "the card as the deck opened it",
        );
        assert_eq!(
            num(&opened["cardScrollTop"]),
            0,
            "the deck opened {item} part-way down: {opened}"
        );
        // The raiser's context is the body region's first block, which is
        // what keeps the answers on the first screen.
        assert_eq!(
            opened["contextInBody"],
            Value::Bool(true),
            "the context is not inside the card's body region on {item}: {opened}"
        );
        for (width, height) in [(390_u32, 844_u32), (820, 1180), (1280, 800)] {
            set_viewport_with(&desk.tab, width, height, width < 700);
            wait_for_js_true(&desk.tab, &format!("innerWidth === {width}"));
            js_value(&desk.tab, SCROLL_CARD_TO_TOP);
            let at = measure(&desk.tab, DECK_STACK_MEASURE, "the stacked deck");
            eprintln!("the stacked deck ({item}) at {width}x{height}: {at}");
            assert_eq!(num(&at["cardScrollTop"]), 0, "{at}");

            // (i) Nothing overflows sideways at any of the three widths.
            assert_eq!(
                num(&at["scrollWidth"]),
                i64::from(width),
                "the deck overflows sideways at {width}x{height}: {at}"
            );
            assert_eq!(num(&at["clientWidth"]), i64::from(width), "{at}");

            // (ii) One answer per row, each as wide as the answers' own column.
            let choices = at["choices"].as_array().expect("the answer buttons");
            assert!(
                choices.len() >= 3,
                "the card carries too few answers to prove a stack: {at}"
            );
            let answers_width = num(&at["answers"]["width"]);
            for choice in choices {
                assert!(
                    (num(&choice["width"]) - answers_width).abs() <= 1,
                    "an answer is not the width of the card's answers at \
                 {width}x{height}: {choice} in {at}"
                );
            }
            for (index, choice) in choices.iter().enumerate() {
                for other in &choices[index + 1..] {
                    assert!(
                        num(&choice["bottom"]) <= num(&other["top"])
                            || num(&other["bottom"]) <= num(&choice["top"]),
                        "two answers share a row at {width}x{height}: {choice} and {other}"
                    );
                }
            }

            // (iii) The panel is not a scroller of its own any more.
            assert_eq!(
                num(&at["panelScrollHeight"]),
                num(&at["panelClientHeight"]),
                "the answer panel scrolls its own content at {width}x{height}: {at}"
            );

            // (iv) The keyboard line is on screen before the card is scrolled,
            // and (vi) the long form scrolls inside its own region without
            // reaching over the answers.
            assert!(
                num(&at["keys"]["top"]) >= 0 && num(&at["keys"]["bottom"]) <= i64::from(height),
                "the keyboard line is off the screen at {width}x{height}: {at}"
            );
            assert!(
                num(&at["body"]["scrollHeight"]) > num(&at["body"]["clientHeight"]),
                "the long form is not the scroller of its own region at \
             {width}x{height}: {at}"
            );
            assert!(
                num(&at["body"]["bottom"]) <= num(&at["panel"]["top"]),
                "the long form reaches over the answers at {width}x{height}: {at}"
            );

            // (v) One scroller, and it reaches the note.
            let landed = js_value(&desk.tab, SCROLL_CARD_TO_END);
            eprintln!("the card's column scrolled to {landed} at {width}x{height}");
            let ended = measure(&desk.tab, DECK_STACK_MEASURE, "the stacked deck, scrolled");
            eprintln!("the stacked deck scrolled to its end at {width}x{height}: {ended}");
            assert_eq!(
                num(&ended["cardScrollTop"]),
                num(&ended["cardScrollHeight"]) - num(&ended["cardClientHeight"]),
                "the card's own column did not reach its end at {width}x{height}: {ended}"
            );
            assert!(
                num(&ended["note"]["top"]) >= 0
                    && num(&ended["note"]["bottom"]) <= i64::from(height),
                "the note is not on the screen after one scroll at {width}x{height}: {ended}"
            );
            assert!(
                num(&ended["note"]["bottom"]) <= num(&ended["keys"]["top"]),
                "the note is under the keyboard line at {width}x{height}: {ended}"
            );
            assert!(
                num(&ended["keys"]["top"]) >= 0
                    && num(&ended["keys"]["bottom"]) <= i64::from(height),
                "scrolling the card took the keyboard line off the screen at \
             {width}x{height}: {ended}"
            );
            assert!(
                num(&ended["panel"]["bottom"]) <= num(&ended["keys"]["top"]),
                "the card's own foot is below the keyboard line at {width}x{height}: {ended}"
            );
            assert!(
                num(&ended["body"]["bottom"]) <= num(&ended["panel"]["top"]),
                "the long form reaches over the answers once scrolled at \
             {width}x{height}: {ended}"
            );

            // (vii) The question is a headline and not a paragraph: it is the
            // largest thing on the card, so its line count is what a viewport
            // has left for the answers.
            let lines = num(&at["headingLines"]);
            // Six lines of 22px on the phone, four of the 28px ceiling above
            // it. One declaration sizes the question at every width since
            // the deck's >=900px `2.25rem`/`1.1` override went, so the
            // longest question the product accepts costs four lines on the
            // desk instead of five.
            let most = if width <= 390 { 6 } else { 4 };
            assert!(
                lines <= most,
                "the question is {lines} lines at {width}x{height}, over {most}: {at}"
            );

            // (viii) And the answer a deck exists to offer is on the screen the
            // card opens on, at every width (George, 2026-09-18: a deck whose
            // recommendation is two scrolls down is not a deck). Measured at the
            // top of the card, which is where a reader arrives.
            assert!(
                num(&at["lead"]["top"]) >= 0 && num(&at["lead"]["bottom"]) <= i64::from(height),
                "the recommended answer is off the first screen at {width}x{height}: {at}"
            );
            assert!(
                num(&at["lead"]["height"]) >= 44,
                "the recommended answer is under a thumb's height at {width}x{height}: {at}"
            );

            // (ix) The priority pill is ABOVE the question, on the eyebrow's
            // line, where it cannot be read as an answer and cannot sit on
            // text that is dissolving into the fade.
            assert!(
                num(&at["pill"]["bottom"]) <= num(&at["heading"]["top"]),
                "the priority pill is below the question at {width}x{height}: {at}"
            );

            // (x) ...and the band between the foot of the long form and the
            // head of the panel holds nothing with text in it. That band is
            // the fade: anything standing in it reads as text that was cut
            // off, which is the complaint this slice answers.
            assert_eq!(
                at["band"].as_array().map(Vec::len),
                Some(0),
                "something with text stands in the fade band at {width}x{height}: {at}"
            );
        }
        seen.push(item.clone());
        // On to the other card, so the sweep is not a claim about one piece
        // of writing. `s` is the deck's own skip, and it is the last input
        // this round makes.
        if card == 0 {
            desk.tab.press_key("s").expect("press s");
            wait_for_js_true(
                &desk.tab,
                &format!("document.querySelector('__CURRENT_CARD__').dataset.item !== '{item}'"),
            );
        }
    }
    assert_eq!(seen.len(), 2, "{seen:?}");
    assert_ne!(
        seen[0], seen[1],
        "the sweep measured the same card twice: {seen:?}"
    );
}

/// Put the reader somewhere inside the card: the card's column to its end
/// and the body region 60px down, with a probe attribute on the node so the
/// measurement afterwards can say whether it is the same node.
///
/// The deck is mounted since `t-1f495a7f`, so a projection swap PATCHES the
/// card the reader is in instead of writing new markup over it. That is the
/// property this places the reader to check: the swap that arrives changes
/// the queue around the card (a third question, at a priority that sorts
/// above it), and both the node and the two scroll positions inside it have
/// to come through that untouched.
const PLACE_THE_READER: &str = "(() => { \
     const card = document.querySelector('__CURRENT_CARD__'); \
     const body = card.querySelector('__DECK_BODY__'); \
     card.scrollTo(0, card.scrollHeight); \
     body.scrollTo(0, 60); \
     card.dataset.probe = 'before the swap'; \
     return JSON.stringify({item: card.dataset.item, card: Math.round(card.scrollTop), \
     body: Math.round(body.scrollTop)}); })()";

/// Where the reader is, and whether the node they are reading is the one
/// they were reading.
const READER_PLACE: &str = "(() => { \
     const card = document.querySelector('__CURRENT_CARD__'); \
     const body = card.querySelector('__DECK_BODY__'); \
     const note = card.querySelector('__DECK_NOTE__').getBoundingClientRect(); \
     const keys = document.querySelector('__DECK_KEYS__').getBoundingClientRect(); \
     return JSON.stringify({item: card.dataset.item, kept: Boolean(card.dataset.probe), \
     card: Math.round(card.scrollTop), body: Math.round(body.scrollTop), \
     noteTop: Math.round(note.top), noteBottom: Math.round(note.bottom), \
     keysTop: Math.round(keys.top), height: innerHeight, \
     cards: document.querySelectorAll('__CARD__').length}); })()";

/// A projection swap does not move the reader inside the card.
///
/// The deck's one scroller is the card's own column since 2026-09-18, which
/// means the position of everything the reader can see is a property of a
/// NODE — and a `/live` notice re-renders the deck two or three times a
/// minute. A re-render that hands back a fresh card puts it at its top: the
/// paragraph being read, the answers and the note all jump while George is
/// looking at them. This is the same mechanism that moved a click target
/// out from under the pointer while this slice was being written, so it is
/// proved rather than assumed: the mounted deck has to reconcile the card
/// the reader is in, not rebuild it.
///
/// The trigger is the ordinary one: another lane raises a card through the
/// CLI, the socket says so, and the page fetches the canonical projection
/// (the path `a_cli_change_reaches_real_chrome_as_a_notice_without_a_reload`
/// proves for the notice itself).
#[test]
fn a_projection_swap_keeps_the_reader_where_they_were_in_the_card_in_real_chrome() {
    let desk = deck_stack_desk("serve-deck-keep-place", "DECKKEEP");
    set_viewport_with(&desk.tab, 390, 844, true);
    wait_for_js_true(&desk.tab, "innerWidth === 390");
    let before = measure(&desk.tab, PLACE_THE_READER, "where the reader was put");
    eprintln!("the reader is at {before}");
    let placed_card = before["card"].as_i64().expect("the card's scrollTop");
    let placed_body = before["body"].as_i64().expect("the body's scrollTop");
    assert!(
        placed_card > 0,
        "the card had nothing to scroll, so this proves nothing: {before}"
    );
    assert_eq!(placed_body, 60, "{before}");

    hold_projection(&desk.tab);
    desk.fixture.ok_json(
        &desk.fixture.main,
        &[
            "attention",
            "raise",
            "A third question arrives while the first one is being read.",
            "--as",
            "codex@driver",
            "--kind",
            "blocking",
            "--priority",
            "2",
            "--json",
        ],
    );
    wait_for_projection_swap(&desk.tab);

    let after = measure(
        &desk.tab,
        READER_PLACE,
        "where the reader is after the swap",
    );
    eprintln!("after the swap the reader is at {after}");
    assert_eq!(
        after["item"], before["item"],
        "the swap changed which card is on screen: {after}"
    );
    assert_eq!(
        after["kept"],
        Value::Bool(true),
        "the swap rebuilt the card the reader was in instead of reconciling \
         it, so the place it kept is an accident: {after}"
    );
    assert_eq!(
        after["cards"].as_i64(),
        Some(3),
        "the projection that replaced it is not the one with the new card: {after}"
    );
    assert_eq!(
        after["card"].as_i64(),
        Some(placed_card),
        "the swap moved the card's own column: {after}"
    );
    assert_eq!(
        after["body"].as_i64(),
        Some(placed_body),
        "the swap moved the long form inside the card: {after}"
    );
    let height = after["height"].as_i64().expect("the viewport height");
    assert!(
        after["noteTop"].as_i64().unwrap_or(-1) >= 0
            && after["noteBottom"].as_i64().unwrap_or(height + 1) <= height,
        "the note is off the screen after the swap: {after}"
    );
    assert!(
        after["noteBottom"].as_i64().unwrap_or(0) <= after["keysTop"].as_i64().unwrap_or(0),
        "the note is under the keyboard line after the swap: {after}"
    );
}

/// `1` sends the answer off and brings the next card, which is the whole
/// point of a deck (George, 2026-09-17: "when i hit 1 it sends it off and
/// gives me the next item via a quick animation").
///
/// The keystroke is the last input this case makes: this driver delivers one
/// `press_key` as thousands of keydowns until one of them is prevented, so
/// the page's own `preventDefault` is what makes a tap one decision -- and
/// anything typed afterwards would be typed into a page still receiving the
/// first key.
#[test]
fn pressing_1_sends_and_advances_to_the_next_card_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, ids) = deck_fixture("serve-deck-advance", "DECKNEXT");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);
    let label = card_choices()[0]["label"].as_str().unwrap().to_owned();
    assert_eq!(
        js_value(&tab, "document.querySelector('.progress').textContent"),
        "3 left"
    );

    hold_projection(&tab);
    tab.press_key("1").expect("press 1");

    // The side history is where a decision lands now: the card it was made
    // on is gone and the next one is in its place. The receipt is read where
    // it lies -- the history is off-canvas until its button is pressed on a
    // narrow window, which hides it without unrendering it.
    wait_for_js_true(
        &tab,
        "Boolean(document.querySelector('__HISTORY_RECEIPT__'))",
    );
    // The decision's own live refresh lands before anything else is asked of
    // the page: a swap replaces every node in `<main>`, and a handle taken
    // before it is a handle to a node that is no longer in the document.
    wait_for_projection_swap(&tab);
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('__HISTORY_RECEIPT__').textContent"
        ),
        format!("Decided: {label}. Undo")
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('__CURRENT__').dataset.item"),
        ids[1].as_str(),
        "the deck did not advance to the next card"
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('.progress').textContent"),
        "2 left",
        "the bar's count disagrees with the queue"
    );
    assert_eq!(
        js_value(
            &tab,
            &format!(
                "document.querySelector('__CARD__[data-item=\"{}\"]') === null",
                ids[0]
            )
        ),
        Value::Bool(true),
        "the decided card is still in the deck"
    );
    // One decision, not a thousand: the digit that arrived again and again
    // for three seconds recorded exactly the card it was pressed on.
    let resolved = fixture.ok_json(
        &fixture.main,
        &["attention", "list", "--status", "resolved", "--json"],
    );
    assert_eq!(
        resolved.as_array().expect("resolved rows").len(),
        1,
        "{resolved}"
    );
    assert_eq!(resolved[0]["id"], ids[0].as_str(), "{resolved}");
    assert_eq!(
        resolved[0]["decision"]["choice"], "assign-and-login",
        "{resolved}"
    );
    assert_eq!(resolved[0]["decision"]["outcome"], "approve", "{resolved}");
    assert_eq!(resolved[0]["decision"]["by"], "geoyws", "{resolved}");
}

/// `s` puts a card at the back of the queue and shows the next one, with
/// nothing recorded: the answer needs thinking about, and the rest of the
/// queue should not wait for it.
///
/// Three skips of a three-card queue bring the first card round again, which
/// is the difference between a skip and a dismissal.
#[test]
fn skip_moves_the_card_to_the_back_without_recording_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, ids) = deck_fixture("serve-deck-skip", "DECKSKIP");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);
    let current = || js_value(&tab, "document.querySelector('__CURRENT__').dataset.item");

    tab.press_key("s").expect("skip the first card");
    wait_for_js_true(
        &tab,
        &format!(
            "document.querySelector('__CURRENT__').dataset.item === \"{}\"",
            ids[1]
        ),
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('.progress').textContent"),
        "3 left",
        "a skip changed how much is open"
    );
    assert_eq!(
        js_value(&tab, "document.querySelectorAll('__HISTORY__ p').length"),
        0,
        "a skip left a receipt"
    );

    tab.press_key("s").expect("skip the second card");
    wait_for_js_true(
        &tab,
        &format!(
            "document.querySelector('__CURRENT__').dataset.item === \"{}\"",
            ids[2]
        ),
    );
    tab.press_key("s").expect("skip the third card");
    wait_for_js_true(
        &tab,
        &format!(
            "document.querySelector('__CURRENT__').dataset.item === \"{}\"",
            ids[0]
        ),
    );
    assert_eq!(current(), ids[0].as_str());

    // Nothing was decided by any of it, and the board says so.
    let open = fixture.ok_json(
        &fixture.main,
        &["attention", "list", "--status", "open", "--json"],
    );
    assert_eq!(open.as_array().expect("open rows").len(), 3, "{open}");
    assert!(
        open.as_array()
            .unwrap()
            .iter()
            .all(|row| row["decision"].is_null()),
        "a skip recorded a decision: {open}"
    );
}

/// A refused decision brings its card back, in a deck that has already moved
/// on to the next one.
///
/// This is what the advance costs: the card leaves the queue the instant the
/// POST is made, so a refusal has to put it back where it was -- on screen,
/// with the board's own words on it, and with nothing left in the history
/// claiming it was decided.
#[test]
fn a_refused_decision_brings_the_card_back_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, ids) = deck_fixture("serve-deck-refused", "DECKREFUSE");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);
    assert_eq!(
        js_value(
            &tab,
            r#"(() => {
  const real = window.fetch;
  window.fetch = (input, init) => {
    if (((init && init.method) || 'GET').toUpperCase() !== 'POST') return real.call(window, input, init);
    return Promise.resolve(new Response('<p class=error>nope</p>', {status: 409}));
  };
  return true;
})()"#
        ),
        true
    );

    tab.press_key("1").expect("press 1");

    let form = ui::decide(&format!("/attention/DECKREFUSE/{}/reply", ids[0]));
    wait_for_js_true(
        &tab,
        &format!(
            "Boolean(document.querySelector('{form} {}'))",
            ui::refusal("board")
        ),
    );
    assert_eq!(
        js_value(
            &tab,
            &format!(
                "document.querySelector('{form} {}').textContent",
                ui::refusal("board")
            )
        ),
        "nope",
        "the card is not quoting what the board said"
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('__CURRENT__').dataset.item"),
        ids[0].as_str(),
        "a refused card did not come back as the card on screen"
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('.progress').textContent"),
        "3 left",
        "a refusal left the queue counting a decision that never happened"
    );
    assert_eq!(
        js_value(&tab, "document.querySelectorAll('__HISTORY__ p').length"),
        0,
        "a refused decision left a row in the history"
    );
    assert_eq!(
        js_value(
            &tab,
            "(() => { const card = document.querySelector('__CURRENT__'); \
             return !card.dataset.state && !card.hasAttribute('aria-busy') && !card.dataset.sent; })()"
        ),
        Value::Bool(true),
        "a refused card is still marked as sending"
    );
    let open = fixture.ok_json(
        &fixture.main,
        &["attention", "list", "--status", "open", "--json"],
    );
    assert_eq!(open.as_array().expect("open rows").len(), 3, "{open}");
}

/// Every receipt of this sitting collects in the side history, newest first,
/// and each one still undoes.
///
/// The receipt used to sit where the card had been, which on a deck is where
/// the NEXT card is: a decision would either overwrite the card in front of
/// the operator or vanish. So the decisions get their own place, with a
/// count on the button that opens it where there is no room for a column.
#[test]
fn decided_receipts_collect_in_the_side_history_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, ids) = deck_fixture("serve-deck-history", "DECKHIST");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);
    set_viewport(&tab, 390, 844);
    wait_for_js_true(&tab, "innerWidth === 390");
    let second = card_choices()[1]["label"].as_str().unwrap().to_owned();
    let rows = "[...document.querySelectorAll('__HISTORY_RECEIPT__')].map(row => row.dataset.item).join(',')";

    // Clicks, not keys: two decisions in one sitting, each on the card the
    // deck put in front of the operator.
    hold_projection(&tab);
    click_control(
        &tab,
        &format!("{} {}", ui::CURRENT_DECIDE, ui::RECOMMENDED_CHOICE),
    );
    wait_for_js_true(
        &tab,
        "document.querySelectorAll('__HISTORY_RECEIPT__').length === 1",
    );
    // The first decision's own live refresh replaces every node in `<main>`,
    // so the second card is only safe to click once that swap has landed.
    wait_for_projection_swap(&tab);
    hold_projection(&tab);
    click_control(
        &tab,
        &format!(
            "{} {}[value=keep-parked]",
            ui::CURRENT_DECIDE,
            ui::ALTERNATIVE_CHOICE
        ),
    );
    wait_for_js_true(
        &tab,
        "document.querySelectorAll('__HISTORY_RECEIPT__').length === 2",
    );

    // Newest first: the decision just made reads at the top.
    assert_eq!(
        js_value(&tab, rows),
        format!("{},{}", ids[1], ids[0]),
        "the history is not newest first"
    );
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('__HISTORY_RECEIPT__').textContent"
        ),
        format!("Decided: {second}. Undo")
    );
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('__HISTORY_COUNT__').textContent"
        ),
        "2",
        "the button that opens the history does not say how much is in it"
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('__CURRENT__').dataset.item"),
        ids[2].as_str()
    );

    // The older row undoes from where it is, and leaves the history when it
    // does: the item is open again and back in the deck.
    wait_for_projection_swap(&tab);
    open_side_history(&tab);
    click_control(
        &tab,
        &format!(
            "{} [data-receipt=\"{}\"] button[data-undo]",
            ui::HISTORY,
            ids[0]
        ),
    );
    wait_for_js_true(
        &tab,
        &format!(
            "document.querySelectorAll('__HISTORY_RECEIPT__').length === 1 \
             && Boolean(document.querySelector('__CARD__[data-item=\"{}\"]'))",
            ids[0]
        ),
    );
    assert_eq!(js_value(&tab, rows), ids[1].as_str());
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('__HISTORY_COUNT__').textContent"
        ),
        "1"
    );
    assert_eq!(
        js_value(&tab, "document.querySelector('__CURRENT__').dataset.item"),
        ids[0].as_str(),
        "an undo has to put the card it brought back in front of the operator"
    );
    let reopened = fixture.ok_json(
        &fixture.main,
        &["attention", "list", "--status", "open", "--json"],
    );
    let row = reopened
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == ids[0].as_str())
        .unwrap_or_else(|| panic!("{} did not come back open: {reopened}", ids[0]));
    assert_eq!(row["decision"], Value::Null, "{row}");
    assert_eq!(row["reopenedBy"], "geoyws", "{row}");
    // The other decision is untouched by the undo of the first.
    let resolved = settled_row(&fixture, &ids[1]);
    assert_eq!(resolved["decision"]["choice"], "keep-parked", "{resolved}");
}

/// Every destination the drawer names answers, with no script anywhere.
///
/// The drawer itself is the bundle's since `t-bf255880` wave 2, and which
/// anchors it holds is read in Chrome. What is read here is the half a
/// browser cannot tell you apart from a mount: that every address the spec
/// names is an address this server answers, with the application, over
/// plain HTTP.
#[test]
fn every_destination_answers_without_a_script_over_http() {
    let (fixture, _ids) = deck_fixture("serve-nav-http", "NAVHTTP");
    let server = spawn_server(&fixture);
    let port = server.port;

    // The spec's nine destinations, in the drawer's own order
    // (`web/src/shell.tsx`'s `DESTINATIONS`).
    let destinations = [
        "/",
        "/all",
        "/decided",
        "/lanes",
        "/boards",
        "/sprints",
        "/plans",
        "/deployments",
        "/subscriptions",
    ];
    for href in destinations {
        let (status, page) = http_get(port, href);
        assert_eq!(status, 200, "GET {href}:\n{page}");
        assert!(
            page.contains("<div id=root data-testid=app-root-shell></div>"),
            "GET {href} did not answer the application:\n{page}"
        );
    }
    // And an address the drawer does not name is not a page: the refusal
    // document, which is the only other thing this server writes.
    let (status, missing) = http_get(port, "/no-such-destination");
    assert_eq!(status, 200, "{missing}");
    assert!(
        missing.contains("No page at that address"),
        "an unnamed address answered something other than the refusal: {missing}"
    );
}

/// `/all` is the whole queue, and it is the application answering it.
///
/// The list stays because a deck is a bad way to read a queue of 133: it is
/// where the whole thing is visible at once. What changed with `t-bf255880`
/// wave 2 is that it is the same mounted application the deck is, reading
/// the same `/api/v1/needs-you` — so what this case measures over HTTP is
/// the two halves the server owes: the document, which carries no rows, and
/// the projection, which carries all of them in the order both surfaces
/// render. The rendered list is measured in Chrome, by the cases `list_tab`
/// drives.
#[test]
fn the_all_route_answers_the_application_and_the_queue_over_http() {
    let (fixture, ids) = deck_fixture("serve-deck-all", "DECKALL");
    let server = spawn_server(&fixture);
    let port = server.port;

    for route in ["/", "/all"] {
        let (status, shell) = http_get(port, route);
        assert_eq!(status, 200, "{shell}");
        assert!(
            shell.contains("<div id=root data-testid=app-root-shell></div>"),
            "{route} is not the application shell: {shell}"
        );
        for data_bearing in [
            "<article class=item",
            "<form class=decide",
            "data-deck-cards",
            "data-testid=app-root>",
            "open across",
        ] {
            assert!(
                !shell.contains(data_bearing),
                "{route} carries {data_bearing}: {shell}"
            );
        }
        for id in &ids {
            assert!(
                !shell.contains(&format!("data-item=\"{id}\"")),
                "{route} carries the queue: {shell}"
            );
        }
    }

    // One queue for both surfaces, in one order, with the long form typeset
    // once by the server's own `markdown`: the deck and the list cannot
    // drift because there is nothing left to drift from.
    let (status, queue) = http_get(port, "/api/v1/needs-you");
    assert_eq!(status, 200, "{queue}");
    let projected: Value = serde_json::from_str(&queue).expect("the queue is JSON");
    let rows = projected["items"].as_array().expect("the queue's rows");
    let served: Vec<&str> = rows
        .iter()
        .map(|card| card["attention"]["id"].as_str().expect("a row id"))
        .collect();
    assert_eq!(
        served,
        ids.iter().map(String::as_str).collect::<Vec<_>>(),
        "the queue is not the seeded rows in deck order:\n{queue}"
    );
    for card in rows {
        let id = card["attention"]["id"].as_str().expect("a row id");
        let typeset = card["bodyHtml"].as_str().expect("the card's bodyHtml");
        assert!(
            !typeset.is_empty(),
            "the card for {id} reached the page with no typeset body: {queue}"
        );
        assert!(
            !typeset.contains("<script"),
            "the raiser's markup was not neutralised for {id}: {typeset}"
        );
    }
}

/// Deciding the LAST card says so at once.
///
/// The card leaves the deck the instant its answer is posted, so on the last
/// one the deck went blank -- no card, no empty state, a progress line
/// reading `0 of 1` -- for the length of a round trip, and longer if the
/// board was slow. The sentence the server ends the queue with is shipped
/// with the deck as a template so the page can say it without waiting.
#[test]
fn the_last_card_leaves_the_empty_state_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let fixture = Fixture::new("serve-deck-empty");
    fixture.ok_json(&fixture.main, &["init", "--name", "DECKEMPTY", "--json"]);
    let item = raise_carded(
        &fixture,
        &long_body("The only card in the queue."),
        "codex@driver",
        &card_args(&["--kind", "blocking", "--priority", "0"], &CARD),
    );
    let id = item["id"].as_str().unwrap();
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);
    let empty_shown = "(() => { const empty = document.querySelector('[data-deck-cards] .empty'); \
                       return Boolean(empty) && empty.checkVisibility(); })()";
    assert_eq!(js_value(&tab, empty_shown), Value::Bool(false));

    hold_projection(&tab);
    tab.press_key("1").expect("press 1");

    // Within the animation and well inside a round trip: the deck never
    // shows an empty frame with nothing in it.
    let deadline = Instant::now() + Duration::from_millis(300);
    while js_value(&tab, empty_shown) != Value::Bool(true) {
        assert!(
            Instant::now() < deadline,
            "the emptied deck said nothing for 300ms: {}",
            js_value(
                &tab,
                "document.querySelector('__DECK_CARDS__').innerHTML.slice(0, 400)"
            )
        );
        std::thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(
        js_value(
            &tab,
            "document.querySelector('[data-deck-cards] .empty').textContent"
        ),
        "Nothing is waiting. Every question an agent raised has an answer."
    );
    // ...and the way on from it is a link, not a dead end. Whoever rendered
    // the empty state -- the page from its template, or the projection that
    // may already have landed -- it is the same block with the same link,
    // which is the point of shipping one wording.
    assert_eq!(
        js_value(
            &tab,
            "(() => { const a = document.querySelector('[data-deck-cards] .empty-queue a'); \
             return a.getAttribute('href') + '|' + a.textContent; })()"
        ),
        "/decided|See what was decided"
    );
    // The bar's count is gone rather than counting a queue that is not
    // there, and the decision is on screen in the history.
    assert_eq!(
        js_value(
            &tab,
            "(() => { const bar = document.querySelector('.progress'); \
             return !bar || bar.hidden; })()"
        ),
        Value::Bool(true),
        "the bar is still counting an empty queue"
    );
    wait_for_js_true(&tab, "Boolean(document.querySelector('__HISTORY__ p'))");

    // And it survives the settle: the server's own empty state arrives with
    // the swap, and there is exactly one of them.
    wait_for_projection_swap(&tab);
    assert_eq!(js_value(&tab, empty_shown), Value::Bool(true));
    assert_eq!(
        js_value(
            &tab,
            "document.querySelectorAll('[data-deck-cards] .empty').length"
        ),
        1,
        "the page and the server both rendered an empty state"
    );
    assert_receipt(&tab, id, card_choices()[0]["label"].as_str().unwrap());
    let row = settled_row(&fixture, id);
    assert_eq!(row["decision"]["choice"], "assign-and-login", "{row}");
}

/// With no script there is no page, and that is the decision (spec SPA-51).
///
/// This case used to assert the opposite — that `/` was a plain list a
/// scriptless browser could answer from (WEB-56, WEB-58) — which was true
/// of a server-rendered deck and is the first accepted cost of ADR-048 §6.
/// It is re-pointed rather than deleted because the claim still needs
/// making, in the other direction: what `/` serves with script execution
/// disabled must be the shell and NOTHING data-bearing, since anything
/// data-bearing there could only come from a second renderer this slice
/// does not keep.
#[test]
fn the_open_page_without_a_script_is_the_shell_and_nothing_else_in_real_chrome() {
    let (fixture, ids) = deck_fixture("serve-deck-nojs", "DECKNOJS");
    let server = spawn_server(&fixture);
    let port = server.port;

    let (status, served) = http_get(port, "/");
    assert_eq!(status, 200, "{served}");
    for id in &ids {
        assert!(
            !served.contains(&format!("data-item=\"{id}\"")),
            "the shell carries {id}: {served}"
        );
    }

    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let chrome = launch_browser(chrome_binary());
    let tab = opened_tab(&chrome, "scriptless tab");
    tab.call_method(Emulation::SetScriptExecutionDisabled { value: true })
        .expect("disable script execution");
    tab.navigate_to(&server.origin()).expect("load Needs you");
    tab.wait_until_navigated().expect("initial navigation");
    // Nothing to wait for but the document itself: the mount is what the
    // disabled script would have done. The measurement is taken through the
    // page's own DOM, which exists whether or not a script ran.
    let measured: Value = serde_json::from_str(
        js_value(
            &tab,
            "JSON.stringify({\
             root: document.querySelectorAll('__APP_ROOT__').length, \
             mount: Boolean(document.querySelector('[data-testid=app-root-shell]')), \
             cards: document.querySelectorAll('__CARD__').length, \
             forms: document.querySelectorAll('__DECIDE__').length, \
             rows: document.querySelectorAll('ul.rows li').length, \
             cells: document.querySelectorAll('td').length, \
             mounted: document.querySelector('[data-testid=app-root-shell]').childElementCount})",
        )
        .as_str()
        .expect("the scriptless measurement"),
    )
    .expect("the scriptless measurement parses");
    eprintln!("no-script /: {measured}");
    assert_eq!(measured["mount"], Value::Bool(true), "{measured}");
    assert_eq!(
        measured["mounted"], 0,
        "something rendered into the mount point with no script: {measured}"
    );
    for empty in ["root", "cards", "forms", "rows", "cells"] {
        assert_eq!(
            measured[empty], 0,
            "the scriptless document is data-bearing in {empty}: {measured}"
        );
    }
}

// --- the spec's own browser-layer cases (docs/specs/web-ui.md §8) -----------
// Every case below is named by that table. They are the half of this slice
// that cannot be read off the stylesheet: what Chrome COMPUTED, on a real
// deck served by the real binary, at the widths George decides on.

/// One deck, one browser, one board behind it: the four lines every §8 case
/// opens with, in one place.
///
/// The field order is the drop order, and it matters: the tab has to go
/// before the browser that owns it, and the server before the fixture whose
/// data directory it is reading.
struct Desk {
    tab: Arc<headless_chrome::Tab>,
    _chrome: Browser,
    server: ServerGuard,
    fixture: Fixture,
    ids: Vec<String>,
}

fn deck_desk(label: &str, board: &str) -> Desk {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, ids) = deck_fixture(label, board);
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &server.origin());
    // `article.item` is in the SERVED markup -- the deck is a plain list
    // until its script runs -- so a case that presses a key the moment the
    // element exists can press it into a page with no key handler yet. The
    // deck is ready when it has made a card current and put the keyboard on
    // it, which is the same act that makes `1` a decision.
    wait_for_js_true(
        &tab,
        "Boolean(document.querySelector('__CURRENT_CARD__')) \
         && document.activeElement === document.querySelector('__CURRENT_CARD__')",
    );
    Desk {
        tab,
        _chrome: chrome,
        server,
        fixture,
        ids,
    }
}

/// The same desk over two cards of deliberately different length: the
/// product's own bounds first ([`LONG_CARD`] at `P0`), the shipped fixture
/// card behind it ([`CARD`] at `P1`). A layout that holds for both holds.
///
/// Its own fixture rather than [`deck_fixture`]'s three: the queue length is
/// on screen as `3 left` and half a dozen cases read it, so a fourth card in
/// the shared fixture would be a sentence changed everywhere to measure a
/// layout here.
fn deck_stack_desk(label: &str, board: &str) -> Desk {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let fixture = Fixture::new(label);
    fixture.ok_json(&fixture.main, &["init", "--name", board, "--json"]);
    let mut ids = Vec::new();
    for (priority, card) in [("0", &LONG_CARD[..]), ("1", &CARD[..])] {
        let item = raise_carded(
            &fixture,
            &long_body("The card the deck is measured on."),
            "codex@driver",
            &card_args(&["--kind", "blocking", "--priority", priority], card),
        );
        ids.push(item["id"].as_str().expect("raised id").to_owned());
    }
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &server.origin());
    wait_for_js_true(
        &tab,
        "Boolean(document.querySelector('__CURRENT_CARD__')) \
         && document.activeElement === document.querySelector('__CURRENT_CARD__')",
    );
    Desk {
        tab,
        _chrome: chrome,
        server,
        fixture,
        ids,
    }
}

/// A design token as the PAGE resolves it, not as a test transcribes it: a
/// probe takes `color:var(--name)` and reports what Chrome computed, so
/// "this fill is `--green`" is one comparison of two computed values. The
/// hexes themselves are pinned at the unit layer (WEB-08).
fn token(tab: &headless_chrome::Tab, name: &str) -> String {
    const PROBE: &str = "(() => { const probe = document.createElement('span'); \
         probe.style.color = 'var(__NAME__)'; document.body.append(probe); \
         const value = getComputedStyle(probe).color; probe.remove(); return value; })()";
    let resolved = js_value(tab, &PROBE.replace("__NAME__", name));
    resolved
        .as_str()
        .unwrap_or_else(|| panic!("resolve {name}: {resolved}"))
        .to_owned()
}

/// Run one JSON measurement in the page and parse it, so a malformed
/// measurement fails by name instead of as a serde error with no context.
fn measure(tab: &headless_chrome::Tab, expression: &str, label: &str) -> Value {
    let raw = js_value(tab, expression);
    let text = raw
        .as_str()
        .unwrap_or_else(|| panic!("{label} did not return a string: {raw}"));
    serde_json::from_str(text).unwrap_or_else(|error| panic!("{label} parses ({error}): {text}"))
}

/// Put the page on one route and wait for it to be the page it names.
fn go(tab: &headless_chrome::Tab, origin: &str, route: &str) {
    let url = format!("{}{}", origin.trim_end_matches('/'), route);
    tab.navigate_to(&url)
        .unwrap_or_else(|error| panic!("load {route}: {error}"));
    tab.wait_until_navigated()
        .unwrap_or_else(|error| panic!("navigate to {route}: {error}"));
    wait_for_js_true(tab, "document.readyState === 'complete'");
    // A route that answers the application shell has nothing in it until
    // the bundle mounts, and `readyState` is complete long before that. The
    // shell is recognised by the node it exists to hold, so this branch
    // needs no list of which routes are mounted -- one more route moving
    // onto the application changes nothing here.
    if js_value(
        tab,
        "document.querySelector('[data-testid=app-root-shell]') !== null",
    ) == Value::Bool(true)
    {
        wait_for_app_root(tab, ui::APP_ROOT);
    }
}

/// Every animation the page starts, recorded at the document so the record
/// survives the projection swap that replaces `<main>`.
const ANIMATION_WATCH: &str = r#"(() => {
  window.__animations = [];
  document.addEventListener('animationstart', event => {
    window.__animations.push({
      name: event.animationName,
      duration: getComputedStyle(event.target).animationDuration,
      item: event.target.dataset ? (event.target.dataset.item || null) : null,
      classes: event.target.className,
    });
  }, true);
  return true;
})()"#;

const HEADLINE_MEASURE: &str = r#"(() => {
  const card = document.querySelector('__CURRENT_CARD__');
  const head = card.querySelector('h2');
  const style = getComputedStyle(head);
  const size = el => parseFloat(getComputedStyle(el).fontSize) || 0;
  const mine = size(head);
  const bigger = [...document.querySelectorAll('body *')]
    .filter(el => el !== head && el.checkVisibility() && size(el) >= mine)
    .map(el => `${el.tagName.toLowerCase()}.${el.className}@${size(el)}`);
  return JSON.stringify({
    width: innerWidth,
    family: style.fontFamily,
    weight: style.fontWeight,
    size: mine,
    lineHeight: parseFloat(style.lineHeight),
    text: head.textContent.slice(0, 48),
    bigger,
  });
})()"#;

/// WEB-02, WEB-07 — the question is set as a headline, and it is the
/// largest thing on the screen.
///
/// The stylesheet's own declarations are pinned at the unit layer; what this
/// case adds is that the cascade actually lands them on the card's `h2` on
/// both screens, and that nothing else on the page grew to match it. The
/// serif is identified by two faces that appear only in the serif stack --
/// a `font-family` that merely ENDS in `serif` would also be the sans
/// stack's `sans-serif`.
///
/// Superseded 2026-09-18: one declaration sizes the question at every width
/// now, `clamp(1.375rem,1.1rem + 1vw,1.75rem)` over `line-height:1.15`, and
/// the deck's own `>=900px` override of `2.25rem`/`1.1` is gone with it. The
/// figures were 28px on the phone and 36px on the desk: 28 spent six lines
/// of a 390x844 screen on a 160-character question before the reader reached
/// the context, and 36 spent five of an 800px-tall desk window on the same
/// question while the answers waited below it (George, 2026-09-18: "it's up
/// but it's squished and not mobile responsive"; "the web version looks
/// mushed up ... (iPad has it squished up)"). The clamp resolves to 22px at
/// 390, 25.8px at 820 and its 28px ceiling at 1280.
#[test]
fn the_question_is_set_as_a_headline_in_real_chrome() {
    let desk = deck_desk("serve-deck-headline", "DECKHEAD");
    for (width, height, floor) in [(390_u32, 844_u32, 22.0_f64), (1280, 800, 28.0)] {
        set_viewport(&desk.tab, width, height);
        wait_for_js_true(&desk.tab, &format!("innerWidth === {width}"));
        let measured = measure(&desk.tab, HEADLINE_MEASURE, "the headline measurement");
        eprintln!("headline at {width}x{height}: {measured}");
        let family = measured["family"].as_str().expect("font-family");
        assert!(
            family.contains("ui-serif") && family.contains("Georgia"),
            "the question is not set in the serif stack at {width}: {measured}"
        );
        assert!(
            !family.contains("-apple-system"),
            "the question is set in the sans stack at {width}: {measured}"
        );
        assert_eq!(measured["weight"], "600", "{measured}");
        let size = measured["size"].as_f64().expect("font-size");
        assert!(
            size >= floor,
            "the question is below the scale's floor of {floor}px at {width}: {measured}"
        );
        assert!(
            measured["lineHeight"].as_f64().expect("line-height") <= size * 1.15 + 0.5,
            "the headline is leaded out at {width}: {measured}"
        );
        assert_eq!(
            measured["bigger"].as_array().expect("bigger").len(),
            0,
            "something on the page is set as large as the question at {width}: {measured}"
        );
    }
}

const FILL_MEASURE: &str = r#"(() => {
  const card = document.querySelector('__CURRENT_CARD__');
  const form = card.querySelector('__DECIDE__');
  const lead = form.querySelector('__RECOMMENDED_CHOICE__');
  const others = [...form.querySelectorAll('__ALTERNATIVE_CHOICE__')];
  const panelStyle = getComputedStyle(form);
  const inner = form.clientWidth
    - parseFloat(panelStyle.paddingLeft) - parseFloat(panelStyle.paddingRight);
  const side = document.querySelector('__SIDE__');
  return JSON.stringify({
    leadBackground: getComputedStyle(lead).backgroundColor,
    leadColor: getComputedStyle(lead).color,
    leadWidth: Math.round(lead.getBoundingClientRect().width),
    panelWidth: Math.round(inner),
    panelBackground: panelStyle.backgroundColor,
    panelSurface: panelStyle.backgroundImage,
    panelStops: (panelStyle.backgroundImage.match(/rgba?\([^)]*\)/g) || []),
    bodyBackground: getComputedStyle(document.body).backgroundColor,
    others: others.map(el => getComputedStyle(el).backgroundColor),
    sideBackground: side && side.checkVisibility()
      ? getComputedStyle(side).backgroundColor : null,
  });
})()"#;

/// WEB-12 — the recommendation leads, on fill.
///
/// The critique this slice answers was that the recommendation did not lead:
/// four outlined boxes of equal weight. So the one filled control on the
/// page is the advised answer, it is filled in its own outcome's hue with
/// the desk colour as its text, it spans the panel, and every alternative is
/// the quiet surface fill. The desk itself is two surfaces and no more.
#[test]
fn the_recommendation_leads_on_fill_in_real_chrome() {
    let desk = deck_desk("serve-deck-fill", "DECKFILL");
    set_viewport(&desk.tab, 1280, 800);
    wait_for_js_true(&desk.tab, "innerWidth === 1280");
    let green = token(&desk.tab, "--green");
    let base = token(&desk.tab, "--base");
    let mantle = token(&desk.tab, "--mantle");
    let surface0 = token(&desk.tab, "--surface0");
    let measured = measure(&desk.tab, FILL_MEASURE, "the fill measurement");
    eprintln!("fills at 1280x800: {measured}");
    // The fixture's recommendation is the `approve` choice, so its fill is
    // the approve hue and nothing else.
    assert_eq!(measured["leadBackground"], green.as_str(), "{measured}");
    assert_eq!(measured["leadColor"], base.as_str(), "{measured}");
    assert_eq!(
        measured["leadWidth"], measured["panelWidth"],
        "the recommendation does not span the answer panel: {measured}"
    );
    let others = measured["others"].as_array().expect("the alternatives");
    assert_eq!(others.len(), 2, "{measured}");
    for fill in others {
        assert_eq!(
            fill,
            &Value::String(surface0.clone()),
            "an alternative is filled like the recommendation: {measured}"
        );
    }
    assert_eq!(measured["bodyBackground"], base.as_str(), "{measured}");
    // The panel's surface is the second desk surface, painted as a gradient
    // whose first two rem are transparent so the card's own text dissolves
    // into it instead of meeting an opaque edge. So the claim is read off
    // the surface rather than off `background-color`: the band on top is
    // clear, everything below it is `--mantle`, and the band is two rem.
    let stops = measured["panelStops"]
        .as_array()
        .expect("the panel's stops");
    assert_eq!(
        stops.len(),
        2,
        "the answer panel is not one two-stop surface: {measured}"
    );
    assert_eq!(
        stops[0], "rgba(0, 0, 0, 0)",
        "the answer panel's top edge is opaque, so text is cut rather than faded: {measured}"
    );
    assert_eq!(
        stops[1],
        mantle.as_str(),
        "the answer panel is not the second desk surface: {measured}"
    );
    assert!(
        measured["panelSurface"]
            .as_str()
            .expect("the panel's surface")
            .contains("32px"),
        "the answer panel's fade is not the two rem the design declares: {measured}"
    );
    assert_eq!(
        measured["sideBackground"],
        mantle.as_str(),
        "the side column is not the second desk surface: {measured}"
    );
    open_nav_drawer(&desk.tab);
    assert_eq!(
        js_value(
            &desk.tab,
            "getComputedStyle(document.querySelector('[data-drawer]')).backgroundColor"
        ),
        mantle.as_str(),
        "the open drawer is not the second desk surface"
    );
}

/// Every drawn border, outline and shadow on the page, with the one
/// allowlisted hairline each carrier is allowed named alongside it.
const BOX_SWEEP: &str = r#"(() => {
  const ALLOW = '__DECIDE__, __RECEIPT__, [aria-current=page], tr, th, td, ul.rows>li, ul.children>li';
  const sides = ['Top', 'Right', 'Bottom', 'Left'];
  const offenders = [];
  const hairlines = [];
  let swept = 0;
  for (const el of document.querySelectorAll('body *')) {
    if (!el.checkVisibility()) continue;
    swept += 1;
    const style = getComputedStyle(el);
    const drawn = sides
      .map(side => ({
        side,
        width: parseFloat(style[`border${side}Width`]) || 0,
        style: style[`border${side}Style`],
        color: style[`border${side}Color`],
      }))
      .filter(edge => edge.width > 0 && edge.style !== 'none');
    const where = `${el.tagName.toLowerCase()}.${el.className}`;
    if (drawn.length > 0) {
      if (!el.matches(ALLOW)) {
        offenders.push({kind: 'border', where, drawn});
      } else if (drawn.length > 1) {
        offenders.push({kind: 'two-sided', where, drawn});
      } else {
        hairlines.push({where, width: drawn[0].width, color: drawn[0].color});
      }
    }
    if (style.boxShadow !== 'none') {
      offenders.push({kind: 'shadow', where, shadow: style.boxShadow});
    }
    const outline = parseFloat(style.outlineWidth) || 0;
    if (outline > 0 && style.outlineStyle !== 'none' && el !== document.activeElement) {
      offenders.push({kind: 'outline', where, outline, style: style.outlineStyle});
    }
  }
  return JSON.stringify({swept, offenders: offenders.slice(0, 12), offences: offenders.length, hairlines});
})()"#;

/// WEB-13 — nothing is boxed.
///
/// The stylesheet's allowlist is a unit test (WEB-09); this is the same
/// claim about what Chrome drew, on every page this slice restyles. The
/// first screenshot round is why it exists: the deck drew a 2px ring around
/// the whole card -- the focus ring, on a card the deck focuses so `1`
/// decides without a click -- and no rule in the stylesheet said so.
///
/// A border is allowed only on the carriers WEB-09 names, only one edge of
/// them, and never as a second edge that would make the row a box again.
#[test]
fn nothing_is_boxed_in_real_chrome() {
    let desk = deck_desk("serve-deck-boxes", "DECKBOX");
    // `/decided` draws decided ROWS, so the sweep is given one: an empty
    // decisions room is a heading and a sentence, and a sweep over that
    // proves nothing about what a row draws.
    desk.fixture.ok_json(
        &desk.fixture.main,
        &[
            "attention",
            "resolve",
            &desk.ids[0],
            "--as",
            "geoyws",
            "--choice",
            "assign-and-login",
            "--json",
        ],
    );
    let origin = desk.server.origin();
    let surface0 = token(&desk.tab, "--surface0");
    let surface1 = token(&desk.tab, "--surface1");
    let text = token(&desk.tab, "--text");
    for route in ["/", "/all", "/decided", "/boards", "/board/DECKBOX"] {
        go(&desk.tab, &origin, route);
        let measured = measure(&desk.tab, BOX_SWEEP, "the box sweep");
        eprintln!("boxes on {route}: {measured}");
        assert!(
            measured["swept"].as_i64().unwrap_or(0) > 10,
            "{route} swept almost nothing, so this proves nothing: {measured}"
        );
        assert_eq!(
            measured["offences"], 0,
            "{route} draws a box, a shadow or an unfocused outline: {measured}"
        );
        // ...and every hairline that IS drawn is the hairline, in one of the
        // two colours the design has for a separator or a rule.
        for hairline in measured["hairlines"].as_array().expect("the hairlines") {
            let width = hairline["width"].as_f64().unwrap_or(0.0);
            let colour = hairline["color"].as_str().unwrap_or_default();
            assert!(
                (width - 1.0).abs() < 0.5 || (width - 2.0).abs() < 0.5 || (width - 3.0).abs() < 0.5,
                "{route} draws a rule that is none of the three the design has: {hairline}"
            );
            assert!(
                colour == surface0
                    || colour == surface1
                    || colour == text
                    || colour.starts_with("rgb("),
                "{route} draws a rule in a colour off the token block: {hairline}"
            );
        }
    }
}

/// Headless Chrome answers `prefers-reduced-motion` with `reduce` unless it
/// is told otherwise, so every case whose subject is motion states the
/// preference it is measuring under. Without this, "nothing animated" would
/// be true of a browser that never animates anything.
fn emulate_motion(tab: &headless_chrome::Tab, value: &str) {
    tab.call_method(Emulation::SetEmulatedMedia {
        media: None,
        features: Some(vec![Emulation::MediaFeature {
            name: "prefers-reduced-motion".to_owned(),
            value: value.to_owned(),
        }]),
    })
    .unwrap_or_else(|error| panic!("emulate prefers-reduced-motion:{value}: {error}"));
    wait_for_js_true(
        tab,
        &format!(
            "matchMedia('(prefers-reduced-motion: reduce)').matches === {}",
            value == "reduce"
        ),
    );
}

/// What the stylesheet resolves the advance to, read off a card the deck is
/// not showing: the two classes the advance is made of, each asked for its
/// computed `animation-name` and put back.
const ADVANCE_PROBE: &str = r#"(() => {
  const probe = [...document.querySelectorAll('__DECK_CARDS__ __CARD__')]
    .find(card => !card.hasAttribute('data-current'));
  const resolve = name => {
    probe.classList.add(name);
    const animation = getComputedStyle(probe).animationName;
    probe.classList.remove(name);
    return animation;
  };
  return JSON.stringify({entering: resolve('entering'), leaving: resolve('leaving')});
})()"#;

/// Every `@keyframes` the document actually parsed, frame by frame, out of
/// the CSSOM rather than out of the source string.
const KEYFRAME_READ: &str = r#"(() => {
  const frames = {};
  for (const sheet of document.styleSheets) {
    for (const rule of sheet.cssRules) {
      if (rule.type !== CSSRule.KEYFRAMES_RULE) continue;
      frames[rule.name] = [...rule.cssRules].map(frame => ({
        at: frame.keyText,
        transform: frame.style.transform,
        opacity: frame.style.opacity,
      }));
    }
  }
  return JSON.stringify(frames);
})()"#;

/// WEB-15 — the advance is 140 ms each way.
///
/// Read as the spec states it: what the leaving and entering nodes COMPUTE.
/// Both resolve to 140ms, the out frame ends 16px to the left and the in
/// frame starts 16px to the right, and one decision produces the advance
/// once — no third animation and no second run of the same one.
///
/// The counted half is deliberately a bound rather than an equality. The
/// leaving card is a ghost the page destroys 140ms after it is made, so on a
/// machine whose first frame after the keystroke takes longer than that, its
/// `animationstart` never fires — a fact about the host's frame budget, not
/// about the advance. What must never happen is a THIRD animation, or a
/// second run of one of the two, and that is what is asserted.
#[test]
fn the_advance_runs_once_at_140ms_each_way_in_real_chrome() {
    let desk = deck_desk("serve-deck-advance-motion", "DECKMOTION");
    // Motion on, explicitly: this case is about the one animation the design
    // has, and a browser that reports a reduced-motion preference would have
    // nothing to measure.
    emulate_motion(&desk.tab, "no-preference");

    // What the two nodes of an advance compute, on a real card.
    let resolved = measure(
        &desk.tab,
        r#"(() => {
  const probe = [...document.querySelectorAll('__DECK_CARDS__ __CARD__')]
    .find(card => !card.hasAttribute('data-current'));
  const resolve = name => {
    probe.classList.add(name);
    const style = getComputedStyle(probe);
    const out = {animation: style.animationName, duration: style.animationDuration};
    probe.classList.remove(name);
    return out;
  };
  return JSON.stringify({entering: resolve('entering'), leaving: resolve('leaving')});
})()"#,
        "the advance's computed animations",
    );
    eprintln!("advance resolves to: {resolved}");
    assert_eq!(resolved["leaving"]["animation"], "deck-out", "{resolved}");
    assert_eq!(resolved["leaving"]["duration"], "0.14s", "{resolved}");
    assert_eq!(resolved["entering"]["animation"], "deck-in", "{resolved}");
    assert_eq!(resolved["entering"]["duration"], "0.14s", "{resolved}");

    // ...and where each of them travels, read off the parsed keyframes.
    let frames = measure(&desk.tab, KEYFRAME_READ, "the keyframes");
    eprintln!("keyframes: {frames}");
    let frame = |name: &str, at: &str| -> String {
        frames[name]
            .as_array()
            .unwrap_or_else(|| panic!("@keyframes {name} is missing: {frames}"))
            .iter()
            .find(|frame| frame["at"] == at)
            .unwrap_or_else(|| panic!("@keyframes {name} has no {at} frame: {frames}"))["transform"]
            .as_str()
            .unwrap_or_default()
            .to_owned()
    };
    assert_eq!(
        frame("deck-out", "100%"),
        "translateX(-16px)",
        "the answered card does not leave 16px to the left: {frames}"
    );
    assert_eq!(
        frame("deck-in", "0%"),
        "translateX(16px)",
        "the next card does not arrive from 16px to the right: {frames}"
    );

    // One decision, and the advance runs once.
    assert_eq!(js_value(&desk.tab, ANIMATION_WATCH), true);
    hold_projection(&desk.tab);
    // The digit is the last input this case makes: the page's own
    // `preventDefault` is what makes one tap one decision.
    desk.tab.press_key("1").expect("press 1");
    wait_for_js_true(
        &desk.tab,
        &format!(
            "document.querySelector('__CURRENT__').dataset.item === \"{}\"",
            desk.ids[1]
        ),
    );
    wait_for_js_true(&desk.tab, "window.__animations.length >= 1");
    // Long enough for a second advance to have started if one were coming.
    std::thread::sleep(Duration::from_millis(400));
    let ran = measure(
        &desk.tab,
        "JSON.stringify({animations: window.__animations})",
        "the advance that ran",
    );
    eprintln!("advance ran: {ran}");
    let animations = ran["animations"].as_array().expect("the animations");
    assert!(
        !animations.is_empty() && animations.len() <= 2,
        "one decision ran the advance {} times: {ran}",
        animations.len()
    );
    let mut names = animations
        .iter()
        .map(|animation| animation["name"].as_str().unwrap_or_default())
        .collect::<Vec<_>>();
    names.sort_unstable();
    names.dedup();
    assert_eq!(
        names.len(),
        animations.len(),
        "the same half of the advance ran twice: {ran}"
    );
    for animation in animations {
        let name = animation["name"].as_str().unwrap_or_default();
        assert!(
            name == "deck-in" || name == "deck-out",
            "something other than the advance animated on a decision: {ran}"
        );
        assert_eq!(
            animation["duration"], "0.14s",
            "the advance is not 140ms: {ran}"
        );
    }
    assert!(
        animations
            .iter()
            .any(|animation| animation["name"] == "deck-in"),
        "the card that arrived did not animate in: {ran}"
    );
}

/// Somebody else's question on the same board: ONE ledger event, so the
/// live socket reports exactly one notice. Two events would be two notices,
/// and a case counting them would be counting the fixture.
fn raise_question(fixture: &Fixture, title: &str) {
    fixture.ok_json(
        &fixture.main,
        &[
            "attention",
            "raise",
            title,
            "--as",
            "codex@driver-2",
            "--kind",
            "decision",
            "--json",
        ],
    );
}

/// Somebody else's task, filed on the same board: also one event, and the
/// notice it becomes carries the task's own title -- which is what makes
/// one notice tellable from the next.
fn file_task(fixture: &Fixture, title: &str, id: &str) {
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            title,
            "--id",
            id,
            "--as",
            "codex@driver-2",
            "--json",
        ],
    );
}

fn sleep_until(when: Instant) {
    let now = Instant::now();
    if when > now {
        std::thread::sleep(when - now);
    }
}

/// WEB-16 — a projection refresh never re-animates the current card.
///
/// George's words were "it keeps blinking": every notice swapped all of
/// `<main>`, so the card being read became a brand new node and the advance
/// ran again underneath the question. The proof has to be about node
/// IDENTITY, so a property is written onto the live node before the refresh
/// and read off whatever node is current afterwards -- markup alone cannot
/// tell a kept node from an identical replacement.
#[test]
fn a_projection_refresh_never_reanimates_the_current_card_in_real_chrome() {
    let desk = deck_desk("serve-deck-blink", "DECKBLINK");
    // Motion on: "the card did not re-animate" has to be a fact about the
    // page rather than about a browser that animates nothing.
    emulate_motion(&desk.tab, "no-preference");
    assert_eq!(
        js_value(&desk.tab, ADVANCE_PROBE),
        "{\"entering\":\"deck-in\",\"leaving\":\"deck-out\"}",
        "the advance is not armed, so an unchanged card could not have blinked"
    );
    wait_for_live_status(&desk.tab, "live", "the deck's first connect");
    assert_eq!(
        js_value(
            &desk.tab,
            "(() => { const card = document.querySelector('__CURRENT_CARD__'); \
             window.__cardAnimations = 0; card.kept = 'the same node'; \
             card.addEventListener('animationstart', () => { window.__cardAnimations += 1; }, true); \
             return card.dataset.item; })()"
        ),
        desk.ids[0].as_str()
    );
    hold_projection(&desk.tab);

    raise_question(&desk.fixture, "An unrelated question from another lane");
    let rows = wait_for_notice_rows(&desk.tab, 1, "the unrelated change");
    assert!(
        rows[0].contains("Attention raised") && rows[0].contains("DECKBLINK"),
        "the other lane's change did not arrive as a notice: {rows:?}"
    );
    wait_for_projection_swap(&desk.tab);

    let measured = measure(
        &desk.tab,
        "(() => { const card = document.querySelector('__CURRENT_CARD__'); \
         return JSON.stringify({item: card.dataset.item, kept: card.kept || null, \
         animations: window.__cardAnimations, entering: card.classList.contains('entering'), \
         running: card.getAnimations().length, queue: \
         document.querySelectorAll('__DECK_CARDS__ __CARD__:not([data-sent])').length}); })()",
        "the refreshed card",
    );
    eprintln!("after the refresh: {measured}");
    assert_eq!(measured["item"], desk.ids[0].as_str(), "{measured}");
    assert_eq!(
        measured["kept"], "the same node",
        "the refresh replaced the card being read: {measured}"
    );
    assert_eq!(
        measured["animations"], 0,
        "the refresh re-animated the card being read -- the blink: {measured}"
    );
    assert_eq!(measured["entering"], false, "{measured}");
    assert_eq!(
        measured["running"], 0,
        "the card being read is still animating after a refresh: {measured}"
    );
    // ...and the refresh DID arrive: the raised question is in the queue, so
    // this is a swap that happened rather than one that never came.
    assert_eq!(
        measured["queue"], 4,
        "the projection did not bring the new question in: {measured}"
    );
}

/// WEB-19 — the toast is readable and dismissible.
///
/// George: "the toast is too fast". Twenty seconds, held while it is being
/// read, gone on `Esc`, and never more than three of them -- measured on the
/// wide desk, where all three have a column to stand in.
#[test]
fn a_toast_stays_twenty_seconds_and_dismisses_in_real_chrome() {
    let desk = deck_desk("serve-deck-toast", "DECKTOAST");
    set_viewport(&desk.tab, 1280, 800);
    wait_for_js_true(&desk.tab, "innerWidth === 1280");
    wait_for_live_status(&desk.tab, "live", "the deck's first connect");

    file_task(&desk.fixture, "The first thing that arrived", "t-toast-1");
    let rows = wait_for_notice_rows(&desk.tab, 1, "the first notice");
    let arrived = Instant::now();
    assert!(rows[0].contains("The first thing that arrived"), "{rows:?}");
    assert_eq!(
        js_value(
            &desk.tab,
            "document.querySelector('__NOTICE__').closest('[role=log]') \
             === document.querySelector('__NOTICES__')"
        ),
        true,
        "a notice arrived outside the log region"
    );

    // Fifteen seconds in, it is still there. The shipped toast went away
    // after six, which is the complaint this number answers.
    sleep_until(arrived + Duration::from_secs(15));
    assert_eq!(
        notice_rows_on_page(&desk.tab).len(),
        1,
        "the toast went away inside twenty seconds"
    );
    // The clock stops while the pointer is on it, so a notice being read is
    // never taken out from under the eye reading it.
    desk.tab
        .find_element(ui::NOTICE)
        .expect("the toast")
        .move_mouse_over()
        .expect("hover the toast");
    wait_for_js_true(
        &desk.tab,
        "Boolean(document.querySelector('__NOTICE__:hover'))",
    );
    sleep_until(arrived + Duration::from_secs(24));
    assert_eq!(
        notice_rows_on_page(&desk.tab).len(),
        1,
        "a hovered toast expired anyway, four seconds past its own life"
    );

    // And `Esc` takes it away at once, from wherever the keyboard is.
    desk.tab.press_key("Escape").expect("press Escape");
    wait_for_js_true(
        &desk.tab,
        "document.querySelectorAll('__NOTICE__').length === 0",
    );

    // Three at most, newest first: the fourth arrival pushes the oldest out.
    let titles = [
        "The second thing that arrived",
        "The third thing that arrived",
        "The fourth thing that arrived",
        "The fifth thing that arrived",
    ];
    for (index, title) in titles.iter().enumerate() {
        file_task(&desk.fixture, title, &format!("t-toast-{}", index + 2));
        wait_for_notice_rows(&desk.tab, std::cmp::min(index + 1, 3), title);
    }
    let stacked = notice_rows_on_page(&desk.tab);
    assert_eq!(stacked.len(), 3, "{stacked:?}");
    assert!(
        stacked[0].contains("The fifth thing that arrived"),
        "the stack is not newest first: {stacked:?}"
    );
    assert!(
        stacked[2].contains("The third thing that arrived"),
        "the stack is not newest first: {stacked:?}"
    );
    assert!(
        !stacked.iter().any(|row| row.contains("The second thing")),
        "a fourth toast did not push the oldest out: {stacked:?}"
    );
}

/// WEB-20 — reduced motion removes the advance too.
///
/// The operator who asks for a still page gets a deck that still advances:
/// the queue moves, nothing slides. The control comes first -- with motion
/// allowed, the two advance classes resolve to the two keyframes -- so the
/// `none` below is the media rule doing its job rather than a browser that
/// never animated anything.
#[test]
fn reduced_motion_advances_the_deck_without_animating_in_real_chrome() {
    let desk = deck_desk("serve-deck-still", "DECKSTILL");
    emulate_motion(&desk.tab, "no-preference");
    assert_eq!(
        js_value(&desk.tab, ADVANCE_PROBE),
        "{\"entering\":\"deck-in\",\"leaving\":\"deck-out\"}",
        "the advance is not armed when motion is allowed, so the rule below proves nothing"
    );
    emulate_motion(&desk.tab, "reduce");
    assert_eq!(
        js_value(&desk.tab, ADVANCE_PROBE),
        "{\"entering\":\"none\",\"leaving\":\"none\"}",
        "the advance still resolves to an animation under reduced motion"
    );
    assert_eq!(js_value(&desk.tab, ANIMATION_WATCH), true);

    hold_projection(&desk.tab);
    desk.tab.press_key("1").expect("press 1");
    wait_for_js_true(
        &desk.tab,
        &format!(
            "document.querySelector('__CURRENT__').dataset.item === \"{}\"",
            desk.ids[1]
        ),
    );
    let measured = measure(
        &desk.tab,
        "JSON.stringify({animations: window.__animations, \
         current: document.querySelector('__CURRENT__').dataset.item, \
         currentAnimation: getComputedStyle(document.querySelector('__CURRENT__')).animationName, \
         left: document.querySelector('.progress').textContent})",
        "the still advance",
    );
    eprintln!("reduced motion: {measured}");
    assert_eq!(
        measured["animations"].as_array().expect("animations").len(),
        0,
        "the deck animated for an operator who asked it not to: {measured}"
    );
    assert_eq!(measured["currentAnimation"], "none", "{measured}");
    assert_eq!(measured["current"], desk.ids[1].as_str(), "{measured}");
    assert_eq!(
        measured["left"], "2 left",
        "the queue did not advance without its animation: {measured}"
    );
}

const DRAWER_MEASURE: &str = r#"(() => {
  const drawer = document.querySelector('[data-drawer]');
  const search = drawer.querySelector('[data-nav-search] input[name=q]');
  const links = [...drawer.querySelectorAll('.nav-links a[href]')];
  const round = value => Math.round(value);
  return JSON.stringify({
    background: getComputedStyle(drawer).backgroundColor,
    searchFirst: links.every(link =>
      search.compareDocumentPosition(link) & Node.DOCUMENT_POSITION_FOLLOWING),
    searchShown: search.checkVisibility(),
    links: links.map(link => {
      const style = getComputedStyle(link);
      const box = link.getBoundingClientRect();
      return {
        nav: link.dataset.nav || null,
        href: link.getAttribute('href'),
        height: round(box.height),
        width: round(box.width),
        separator: parseFloat(style.borderBottomWidth) || 0,
        separatorColor: style.borderBottomColor,
        background: style.backgroundColor,
        leftRule: parseFloat(style.borderLeftWidth) || 0,
        leftColor: style.borderLeftColor,
        current: link.getAttribute('aria-current'),
      };
    }),
  });
})()"#;

/// WEB-36 — the drawer is rows on the desk surface.
///
/// Not a panel of tiles: the second desk surface, one row per destination,
/// separated by the one hairline, with the search field above all of them --
/// and every row a thumb can hit.
#[test]
fn the_drawer_is_rows_on_the_desk_surface_in_real_chrome() {
    let desk = deck_desk("serve-deck-drawer", "DECKDRAWER");
    set_viewport(&desk.tab, 390, 844);
    wait_for_js_true(&desk.tab, "innerWidth === 390");
    let mantle = token(&desk.tab, "--mantle");
    let surface0 = token(&desk.tab, "--surface0");
    open_nav_drawer(&desk.tab);
    let measured = measure(&desk.tab, DRAWER_MEASURE, "the drawer measurement");
    eprintln!("drawer at 390x844: {measured}");
    assert_eq!(measured["background"], mantle.as_str(), "{measured}");
    assert_eq!(
        measured["searchFirst"], true,
        "search is not above every destination: {measured}"
    );
    assert_eq!(measured["searchShown"], true, "{measured}");
    let links = measured["links"].as_array().expect("the destinations");
    assert!(
        links.len() >= 9,
        "the drawer is missing destinations: {measured}"
    );
    for link in links {
        assert!(
            link["height"].as_f64().unwrap_or(0.0) >= 44.0,
            "a destination row is smaller than a thumb: {link}"
        );
        assert_eq!(
            link["separator"].as_f64().unwrap_or(0.0),
            1.0,
            "a destination is not separated by the one hairline: {link}"
        );
        assert_eq!(
            link["separatorColor"],
            surface0.as_str(),
            "the separator is not the hairline colour: {link}"
        );
    }
}

/// WEB-37 — the current page is marked by a rule, not a fill.
///
/// One 2px rule in the text colour on the destination the page is, and
/// nothing on any other -- checked on two of them, because a mark that is
/// right on one page and stuck there is not a mark of where you are.
#[test]
fn the_current_page_is_marked_by_a_rule_in_real_chrome() {
    let desk = deck_desk("serve-deck-current", "DECKHERE");
    let origin = desk.server.origin();
    let text = token(&desk.tab, "--text");
    for (route, nav) in [("/", "needs-you"), ("/decided", "decided")] {
        go(&desk.tab, &origin, route);
        open_nav_drawer(&desk.tab);
        let measured = measure(&desk.tab, DRAWER_MEASURE, "the drawer measurement");
        eprintln!("current page on {route}: {measured}");
        let drawer_background = measured["background"].as_str().expect("the drawer's fill");
        let links = measured["links"].as_array().expect("the destinations");
        let marked = links
            .iter()
            .filter(|link| link["current"] == "page")
            .collect::<Vec<_>>();
        assert_eq!(
            marked.len(),
            1,
            "{route} marks {} destinations as current: {measured}",
            marked.len()
        );
        let here = marked[0];
        assert_eq!(
            here["nav"], nav,
            "{route} marks the wrong destination: {here}"
        );
        assert_eq!(
            here["leftRule"].as_f64().unwrap_or(0.0),
            2.0,
            "{route}'s own destination carries no 2px rule: {here}"
        );
        assert_eq!(
            here["leftColor"],
            text.as_str(),
            "{route}'s rule is not in the text colour: {here}"
        );
        assert_eq!(
            here["background"], drawer_background,
            "{route}'s destination is marked by a fill rather than a rule: {here}"
        );
        for link in links {
            if link["current"] == "page" {
                continue;
            }
            assert_eq!(
                link["leftRule"].as_f64().unwrap_or(0.0),
                0.0,
                "{route} rules a destination that is not where we are: {link}"
            );
        }
    }
}

const WIDTH_SWEEP: &str = r#"(() => {
  const doc = document.documentElement;
  let widest = null;
  let edge = 0;
  for (const el of document.querySelectorAll('body *')) {
    if (!el.checkVisibility()) continue;
    const right = Math.round(el.getBoundingClientRect().right);
    if (right > edge) { edge = right; widest = el; }
  }
  return JSON.stringify({
    scrollWidth: doc.scrollWidth,
    clientWidth: doc.clientWidth,
    innerWidth,
    heading: (document.querySelector('h1') || {textContent: ''}).textContent.trim(),
    text: document.body.innerText.slice(0, 2400),
    widest: widest ? `${widest.tagName.toLowerCase()}.${widest.className}@${edge}` : null,
    fragment: Boolean(document.querySelector('[data-preview-card]')),
    // WEB-03, read where the headings and links now live: the rendered
    // page. Nothing the application writes may be prefixed with a glyph or
    // trail an arrow.
    glyphs: [...document.querySelectorAll('h1, h2, a')]
      .map(el => el.textContent.trim())
      .filter(text => text.startsWith('>') || text.endsWith('\u2192')),
  });
})()"#;

/// The server's own source, for the one thing about the server that a test
/// cannot observe from outside it: which shapes `render` answers at all. The
/// registry is declared next to that match as `ROUTE_SHAPES`, and a unit test
/// in `serve.rs` holds the registry to the match's arm count -- so parsing it
/// here closes the loop without making a module public for a test's sake.
const SERVE_SOURCE: &str = include_str!("../rust/serve.rs");

/// The shapes `serve.rs` declares, in the order it declares them.
fn declared_route_shapes() -> Vec<String> {
    let block = SERVE_SOURCE
        .split_once("const ROUTE_SHAPES: &[&str] = &[")
        .expect("serve.rs declares ROUTE_SHAPES")
        .1
        .split_once("];")
        .expect("the registry closes")
        .0;
    let mut shapes = Vec::new();
    let mut rest = block;
    while let Some(at) = rest.find('"') {
        let after = &rest[at + 1..];
        let end = after.find('"').expect("the shape closes");
        shapes.push(after[..end].to_owned());
        rest = &after[end + 1..];
    }
    assert!(!shapes.is_empty(), "the registry declares no shapes");
    shapes
}

/// WEB-44 — nothing overflows sideways, anywhere.
///
/// Every route `render` answers, on a board seeded with one of everything
/// those routes list, at the three widths George reads on. A sideways
/// scrollbar on a phone is the read pages' commonest way of breaking, and
/// one route measured is one route proved -- so this sweeps them all, and
/// names the widest element when one of them fails.
///
/// "Them all" is held to the server rather than to this list: every shape
/// loaded here is checked against `serve.rs`'s own `ROUTE_SHAPES`, which its
/// unit test holds to `render`'s arm count. The hover previews left the
/// sweep with `t-bf255880` wave 2: they are not routes any more, they are
/// `/api/v1/preview/...` reads the page builds its own card from, and they
/// are measured where they are rendered (SPA-40).
#[test]
fn no_route_overflows_sideways_at_three_widths_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, _ids) = deck_fixture("serve-deck-routes", "DECKROUTES");
    fixture.ok_json(
        &fixture.main,
        &["tag", "add", "sweep", "--as", "fixture-agent", "--json"],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "A drafted plan the sweep can read",
            "--id",
            "e-routes",
            "--type",
            "epic",
            "--status",
            "draft",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "A task the routes sweep can open",
            "--id",
            "t-routes",
            "--type",
            "task",
            "--status",
            "todo",
            "--parent",
            "e-routes",
            "--tag",
            "sweep",
            "--body",
            "The seeded task's body, written out at the width a raiser writes \
             it so that a narrow screen has something to wrap.",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "new",
            "The sweep's own sprint",
            "--id",
            "sp-routes",
            "--target-version",
            "9.9.9",
            "--start",
            "0",
            "--end",
            "4102444800000",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sprint",
            "plan",
            "sp-routes",
            "--body",
            "Ship the sweep.",
            "--candidate",
            "t-routes",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "sitrep",
            "post",
            "The sweep lane has the seeded task in hand.",
            "--as",
            "fixture-agent",
            "--lane",
            "sweep-lane",
            "--task",
            "t-routes",
            "--json",
        ],
    );
    let deployment = fixture.ok_json(
        &fixture.main,
        &[
            "deploy",
            "start",
            "--repo",
            "geoyws/kanban-sweep",
            "--commit",
            "cccccccccccccccccccccccccccccccccccccccc",
            "--tier",
            "@_bd",
            "--environment",
            "sweep-fixture",
            "--host",
            "geoywsMBP",
            "--url",
            "http://127.0.0.1:14300",
            "--task",
            "t-routes",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    let deployment_id = deployment["id"]
        .as_str()
        .expect("the deployment")
        .to_owned();
    fixture.ok_json(
        &fixture.main,
        &[
            "subscription",
            "add",
            "--id",
            "sub-routes",
            "--subject",
            "task:t-routes",
            "--relation",
            "parent:e-routes",
            "--kind",
            "checkpoint_added",
            "--prior-status",
            "todo",
            "--current-status",
            "in_progress",
            "--tag",
            "sweep",
            "--consumer",
            "codex.queue",
            "--action",
            "enqueue-turn",
            "--timeout-ms",
            "30000",
            "--max-retries",
            "3",
            "--rate-per-minute",
            "60",
            "--max-concurrency",
            "1",
            "--secret-ref",
            "codex_queue_token",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );

    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = decision_tab(&chrome, &origin);

    let deployment_route = format!("/deployment/DECKROUTES/{deployment_id}");
    // Shape, URL, and the seeded record the page must actually have rendered.
    // The shape is what the registry is compared against; the not-found arm
    // is the one route with no shape of its own to declare.
    let routes: Vec<(&str, &str, Option<&str>)> = vec![
        ("/", "/", Some("DECKROUTES")),
        ("/all", "/all", Some("open across")),
        ("/decided", "/decided", None),
        ("/boards", "/boards", Some("DECKROUTES")),
        (
            "/board/{project}",
            "/board/DECKROUTES",
            Some("A task the routes sweep can open"),
        ),
        ("/lanes", "/lanes", Some("sweep-lane")),
        ("/sprints", "/sprints", Some("The sweep's own sprint")),
        (
            "/sprints/{project}",
            "/sprints/DECKROUTES",
            Some("The sweep's own sprint"),
        ),
        (
            "/sprint/{project}/{id}",
            "/sprint/DECKROUTES/sp-routes",
            Some("Ship the sweep."),
        ),
        (
            "/plans",
            "/plans",
            Some("A drafted plan the sweep can read"),
        ),
        ("/deployments", "/deployments", Some("geoyws/kanban-sweep")),
        ("/subscriptions", "/subscriptions", Some("sub-routes")),
        ("/search", "/search?q=sweep", Some("sweep")),
        (
            "/task/{project}/{id}",
            "/task/DECKROUTES/t-routes",
            Some("A task the routes sweep can open"),
        ),
        (
            "/deployment/{project}/{id}",
            deployment_route.as_str(),
            Some("geoyws/kanban-sweep"),
        ),
        ("", "/no-such-page", Some("No page at that address")),
    ];

    // The list is held to the server: every shape `render` answers is loaded
    // here, so an arm added without a route in this sweep fails rather than
    // going unmeasured on a phone.
    let mut swept = routes
        .iter()
        .map(|(shape, _, _)| (*shape).to_owned())
        .filter(|shape| !shape.is_empty())
        .collect::<Vec<_>>();
    swept.sort();
    swept.dedup();
    let mut declared = declared_route_shapes();
    declared.sort();
    declared.dedup();
    assert_eq!(
        swept, declared,
        "the width sweep does not load every shape render answers"
    );

    for (shape, route, marker) in routes {
        // Every shape is a mounted page since `t-bf255880` wave 2: the
        // preview fragments left with the server-rendered pages, and a
        // hover now reads `/api/v1/preview/...` and builds its own card.
        // A route the client mounts has nothing to measure until it has
        // read its projection: the server sends the shell, and the seeded
        // record arrives one fetch later. Waiting for the record rather
        // than for the root is what makes the marker assertion below an
        // assertion instead of a race. After `t-bf255880` wave 2 that is
        // every shape: only the not-found arm is still a served page.
        let mounted = !shape.is_empty();
        for (width, height) in [(390_u32, 844_u32), (820, 1180), (1280, 800)] {
            set_viewport_with(&tab, width, height, width < 700);
            go(&tab, &origin, route);
            if mounted {
                wait_for_app_root(&tab, ui::APP_ROOT);
                if let Some(marker) = marker {
                    let literal = serde_json::to_string(marker).expect("the marker as a JS string");
                    wait_for_js_true(
                        &tab,
                        &format!("document.body.innerText.includes({literal})"),
                    );
                }
            }
            wait_for_js_true(&tab, &format!("innerWidth === {width}"));
            let measured = measure(&tab, WIDTH_SWEEP, "the width sweep");
            let scroll = measured["scrollWidth"].as_i64().expect("scrollWidth");
            let client = measured["clientWidth"].as_i64().expect("clientWidth");
            eprintln!(
                "{route} at {width}x{height}: scrollWidth {scroll} clientWidth {client} widest {}",
                measured["widest"]
            );
            assert!(
                scroll <= client,
                "{route} overflows sideways at {width}x{height}: scrollWidth {scroll} > \
                 clientWidth {client}, widest {}",
                measured["widest"]
            );
            assert_eq!(
                measured["fragment"],
                Value::Bool(false),
                "{route} rendered a preview fragment at {width}x{height}: {}",
                measured["text"]
            );
            assert!(
                !measured["heading"]
                    .as_str()
                    .expect("the page's heading")
                    .is_empty(),
                "{route} rendered no heading at {width}x{height}, so nothing was measured"
            );
            // WEB-03 — no glyph prefix and no trailing arrow, on any
            // heading or link of any route. The claim was made against the
            // served markup until `t-bf255880` wave 2 deleted it; this is
            // the same claim against what the reader actually gets.
            assert_eq!(
                measured["glyphs"],
                serde_json::json!([]),
                "{route} carries a glyph-prefixed heading or link at {width}x{height}"
            );
            if let Some(marker) = marker {
                assert!(
                    measured["text"]
                        .as_str()
                        .expect("the page's text")
                        .contains(marker),
                    "{route} did not render its seeded record ({marker}) at {width}x{height}: {}",
                    measured["text"]
                );
            }
        }
    }
}

const THUMB_SWEEP: &str = r#"(() => {
  const small = [];
  let counted = 0;
  const sweep = (scope, where) => {
    if (!scope) return;
    for (const el of scope.querySelectorAll('button, input, textarea, summary, a')) {
      if (!el.checkVisibility()) continue;
      // A radio's hit target is the pill its label draws around it, which is
      // what a thumb lands on; the input itself is a 14px dot by design.
      const target = el.matches('input[type=radio]') ? (el.closest('label') || el) : el;
      const box = target.getBoundingClientRect();
      counted += 1;
      if (box.height < 44 || box.width < 44) {
        small.push({
          where,
          what: `${el.tagName.toLowerCase()}.${el.className}`,
          height: Math.round(box.height),
          width: Math.round(box.width),
        });
      }
    }
  };
  sweep(document.querySelector('__CURRENT_CARD__ __DECIDE__'), 'panel');
  sweep(document.querySelector('nav:not(.drawer)'), 'bar');
  return JSON.stringify({counted, small});
})()"#;

/// WEB-45 — a thumb can hit every deck control.
///
/// 44 CSS px is the platform floor George decides on, and it is asserted on
/// the two places a thumb goes: the answer panel and the bar above it. The
/// fold is opened and the sweep run again, because the free-text answer's
/// own submit is a control a thumb has to hit too.
#[test]
fn every_deck_control_is_forty_four_pixels_at_390_in_real_chrome() {
    let desk = deck_desk("serve-deck-thumb", "DECKTHUMB");
    set_viewport(&desk.tab, 390, 844);
    wait_for_js_true(&desk.tab, "innerWidth === 390");
    let measured = measure(&desk.tab, THUMB_SWEEP, "the thumb sweep");
    eprintln!("controls at 390x844: {measured}");
    assert!(
        measured["counted"].as_i64().unwrap_or(0) >= 6,
        "the sweep found almost no controls, so it proves nothing: {measured}"
    );
    assert_eq!(
        measured["small"]
            .as_array()
            .expect("the small controls")
            .len(),
        0,
        "a deck control is smaller than a thumb at 390: {measured}"
    );

    let form = ui::decide(&format!("/attention/DECKTHUMB/{}/reply", desk.ids[0]));
    open_custom_answer(&desk.tab, &format!("{} {form}", ui::CURRENT));
    let unfolded = measure(&desk.tab, THUMB_SWEEP, "the thumb sweep, unfolded");
    eprintln!("controls with the fold open at 390x844: {unfolded}");
    assert!(
        unfolded["counted"].as_i64().unwrap_or(0) > measured["counted"].as_i64().unwrap_or(0),
        "opening the fold revealed no further controls: {unfolded}"
    );
    assert_eq!(
        unfolded["small"]
            .as_array()
            .expect("the small controls")
            .len(),
        0,
        "a control inside the free-text answer is smaller than a thumb at 390: {unfolded}"
    );
}

const DESK_MEASURE: &str = r#"(() => {
  const deck = document.querySelector('__DECK_CARDS__');
  const side = document.querySelector('__SIDE__');
  const history = document.querySelector('__HISTORY__');
  const toggle = document.querySelector('__HISTORY_TOGGLE__');
  const rect = el => {
    const box = el.getBoundingClientRect();
    return {left: Math.round(box.left), right: Math.round(box.right), width: Math.round(box.width)};
  };
  return JSON.stringify({
    width: innerWidth,
    deck: rect(deck),
    side: side.checkVisibility() ? rect(side) : null,
    sideBackground: side.checkVisibility() ? getComputedStyle(side).backgroundColor : null,
    history: rect(history),
    toggleShown: Boolean(toggle) && toggle.checkVisibility(),
    open: document.body.hasAttribute('data-history-open'),
  });
})()"#;

/// WEB-46 — the desk becomes two columns on a Mac, and a drawer between.
///
/// At 1280 the session's decisions stand beside the deck in a column of
/// their own on the second desk surface; at 820 that column is a drawer
/// behind a button, off the canvas until the button is pressed, and back off
/// it when the button is pressed again.
#[test]
fn the_desk_is_two_columns_at_1280_and_a_drawer_at_820_in_real_chrome() {
    let desk = deck_desk("serve-deck-columns", "DECKCOLS");
    let mantle = token(&desk.tab, "--mantle");

    set_viewport(&desk.tab, 1280, 800);
    wait_for_js_true(&desk.tab, "innerWidth === 1280");
    let wide = measure(&desk.tab, DESK_MEASURE, "the desk at 1280");
    eprintln!("desk at 1280x800: {wide}");
    let side = wide["side"].as_object().unwrap_or_else(|| {
        panic!("the side is not a column at 1280: {wide}");
    });
    assert_eq!(
        side["width"].as_f64().unwrap_or(0.0),
        352.0,
        "the side column is not 22rem wide: {wide}"
    );
    assert!(
        side["left"].as_f64().unwrap_or(0.0) >= wide["deck"]["right"].as_f64().unwrap_or(0.0),
        "the side column is not beside the deck: {wide}"
    );
    assert!(
        wide["deck"]["width"].as_f64().unwrap_or(0.0) <= 704.0,
        "the deck column is wider than 44rem: {wide}"
    );
    assert_eq!(wide["sideBackground"], mantle.as_str(), "{wide}");
    assert_eq!(
        wide["toggleShown"], false,
        "the history button is there beside the column it opens: {wide}"
    );

    set_viewport(&desk.tab, 820, 1180);
    wait_for_js_true(&desk.tab, "innerWidth === 820");
    let narrow = measure(&desk.tab, DESK_MEASURE, "the desk at 820");
    eprintln!("desk at 820x1180: {narrow}");
    assert_eq!(
        narrow["side"],
        Value::Null,
        "the side is still a column at 820: {narrow}"
    );
    assert_eq!(
        narrow["toggleShown"], true,
        "there is no button to open the history with at 820: {narrow}"
    );
    assert!(
        narrow["history"]["left"].as_f64().unwrap_or(0.0) >= 820.0,
        "the history drawer is on the canvas before it was opened: {narrow}"
    );

    click_control(&desk.tab, ui::HISTORY_TOGGLE);
    wait_for_js_true(
        &desk.tab,
        "document.body.hasAttribute('data-history-open') \
         && document.querySelector('__HISTORY__').getBoundingClientRect().left < innerWidth - 1",
    );
    let opened = measure(&desk.tab, DESK_MEASURE, "the opened drawer");
    eprintln!("history drawer at 820x1180: {opened}");
    assert!(
        opened["history"]["right"].as_f64().unwrap_or(0.0) <= 821.0
            && opened["history"]["width"].as_f64().unwrap_or(0.0) > 100.0,
        "the opened drawer is not on the screen: {opened}"
    );

    // And it goes away again the way it is offered: while it is open its own
    // button is behind the backdrop, which is the drawer pattern -- a press
    // outside it is what shuts it.
    click_control(&desk.tab, "[data-backdrop]");
    wait_for_js_true(
        &desk.tab,
        "!document.body.hasAttribute('data-history-open') \
         && document.querySelector('__HISTORY__').getBoundingClientRect().left >= innerWidth - 1 \
         && document.querySelector('[data-backdrop]').hidden",
    );
}

const FOCUSED_MEASURE: &str = r#"(() => {
  const el = document.activeElement;
  if (!el || el === document.body || el === document.documentElement) {
    return JSON.stringify({what: null});
  }
  const style = getComputedStyle(el);
  return JSON.stringify({
    what: `${el.tagName.toLowerCase()}.${el.className}`,
    card: el.matches('__CURRENT_CARD__'),
    width: parseFloat(style.outlineWidth) || 0,
    style: style.outlineStyle,
    color: style.outlineColor,
  });
})()"#;

/// WEB-51 — focus is always visible.
///
/// Tab through the deck and then through a read page, and every element the
/// keyboard lands on says so with the one ring. The documented exception is
/// the current card itself: the deck focuses it so `1` decides without a
/// click first, and a permanent 2px ring around the whole card is the box
/// WEB-13 forbids -- every control inside it still rings.
#[test]
fn focus_is_visible_on_every_focusable_element_in_real_chrome() {
    let desk = deck_desk("serve-deck-focus", "DECKFOCUS");
    let origin = desk.server.origin();
    let focus = token(&desk.tab, "--focus");
    for (route, steps) in [("/", 14), ("/boards", 8)] {
        go(&desk.tab, &origin, route);
        let mut rung = 0;
        for step in 0..steps {
            desk.tab.press_key("Tab").expect("tab to the next element");
            let measured = measure(&desk.tab, FOCUSED_MEASURE, "the focused element");
            if measured["what"] == Value::Null {
                continue;
            }
            eprintln!("{route} focus step {step}: {measured}");
            if measured["card"] == true {
                continue;
            }
            assert!(
                measured["style"].as_str().unwrap_or("none") != "none",
                "{route} gives the keyboard no ring on {}: {measured}",
                measured["what"]
            );
            assert!(
                measured["width"].as_f64().unwrap_or(0.0) >= 2.0,
                "{route}'s focus ring is thinner than 2px on {}: {measured}",
                measured["what"]
            );
            assert_eq!(
                measured["color"],
                focus.as_str(),
                "{route}'s focus ring is not the focus token on {}: {measured}",
                measured["what"]
            );
            rung += 1;
        }
        assert!(
            rung >= 4,
            "{route} never put the keyboard on four elements, so nothing was proved"
        );
    }
}

/// WEB-53 — the card is named by its question.
///
/// A screen reader announces the card by its accessible name, and that name
/// has to be the question rather than "article". It is computed the way the
/// accessibility tree computes it: `aria-labelledby` resolved to the text of
/// the elements it names.
#[test]
fn the_card_is_named_by_its_question_in_real_chrome() {
    let desk = deck_desk("serve-deck-named", "DECKNAME");
    let measured = measure(
        &desk.tab,
        r#"(() => {
  const card = document.querySelector('__CURRENT_CARD__');
  const ids = (card.getAttribute('aria-labelledby') || '').split(/\s+/).filter(Boolean);
  const named = ids.map(id => {
    const el = document.getElementById(id);
    return el ? el.textContent.trim() : null;
  });
  return JSON.stringify({
    ids,
    named,
    name: named.filter(Boolean).join(' '),
    question: card.querySelector('h2').textContent.trim(),
    role: card.getAttribute('role'),
  });
})()"#,
        "the card's accessible name",
    );
    eprintln!("the card's name: {measured}");
    assert_eq!(
        measured["ids"].as_array().expect("the labelling ids").len(),
        1,
        "the card is named by something other than its one question: {measured}"
    );
    assert_eq!(
        measured["named"][0], measured["question"],
        "the card's aria-labelledby does not resolve to its question: {measured}"
    );
    // ...and the question is the raiser's own, not a placeholder that would
    // satisfy the resolution while naming nothing.
    assert_eq!(measured["name"], CARD[1], "{measured}");
}

/// The composer's own refusal, verbatim. It is one fixed sentence, it never
/// names which half is missing, and it is the PAGE's sentence -- the CLI has
/// its own words for the same case (`INCOMPLETE_ANSWER` above).
const PAGE_INCOMPLETE_ANSWER: &str = "Your own answer needs both halves: pick a verdict \
                                      (approve, reject, defer or other) and write your reply.";

/// WEB-57 — the composer's own refusal is its own sentence, in its own
/// channel.
///
/// A free-text answer with a reply and no verdict is not an answer, and the
/// page says so before it posts anything: its own sentence in its own
/// channel, the cursor on the missing half, and the board untouched.
#[test]
fn an_incomplete_own_answer_refuses_before_posting_in_real_chrome() {
    let desk = deck_desk("serve-deck-incomplete", "DECKHALF");
    let form = ui::CURRENT_DECIDE;
    // Every POST this page makes, recorded where it is made. The projection
    // GET goes through the same `fetch` and is deliberately not counted.
    assert_eq!(
        js_value(
            &desk.tab,
            r#"(() => {
  const real = window.fetch;
  window.__posts = [];
  window.fetch = (input, init) => {
    if (((init && init.method) || 'GET').toUpperCase() === 'POST') {
      window.__posts.push(String((input && input.url) || input));
    }
    return real.call(window, input, init);
  };
  return true;
})()"#
        ),
        true
    );
    open_custom_answer(&desk.tab, form);
    let reply = desk
        .tab
        .wait_for_element(&format!("{form} textarea[name=reply]"))
        .expect("the reply field");
    reply.click().expect("focus the reply field");
    reply
        .type_into("Assign the seat, but bill it to the platform budget.")
        .expect("type the reply");
    click_control(&desk.tab, &format!("{form} button.record"));

    wait_for_js_true(
        &desk.tab,
        &format!(
            "Boolean(document.querySelector('{form} {}'))",
            ui::error_refusal("incomplete")
        ),
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!(
                "document.querySelector('{form} {}').textContent",
                ui::error_refusal("incomplete")
            )
        ),
        PAGE_INCOMPLETE_ANSWER,
        "the composer's refusal is not its own sentence"
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!(
                "document.activeElement === document.querySelector('{form} input[name=outcome]')"
            )
        ),
        true,
        "the cursor is not on the half that is missing"
    );
    // ...and the refusal is inline text tied to that half, not a third
    // announcement channel. The page has exactly two -- the socket's status
    // line and the toast log -- and a refusal that shouted through a third
    // was the page narrating itself, which WEB-52 forbids.
    let announced = measure(
        &desk.tab,
        r#"(() => {
  const regions = [...document.querySelectorAll('[role=status],[role=log],[role=alert],[aria-live]')];
  const refusal = document.querySelector('__ERROR__[data-refusal=incomplete]');
  const focused = document.activeElement;
  return JSON.stringify({
    roles: regions.map(el => el.getAttribute('role') || `aria-live=${el.getAttribute('aria-live')}`),
    alerts: regions.filter(el => el.getAttribute('role') === 'alert').length,
    refusalRole: refusal.getAttribute('role'),
    refusalLive: refusal.getAttribute('aria-live'),
    refusalId: refusal.id,
    describedBy: focused.getAttribute('aria-describedby'),
  });
})()"#,
        "the page's announcement channels with a refusal on screen",
    );
    eprintln!("channels while refused: {announced}");
    assert_eq!(
        announced["roles"].as_array().expect("the regions").len(),
        2,
        "a refusal opened a third announcement channel: {announced}"
    );
    assert_eq!(
        announced["alerts"], 0,
        "the refusal is announced as an alert instead of read as the text it is: {announced}"
    );
    assert_eq!(announced["refusalRole"], Value::Null, "{announced}");
    assert_eq!(announced["refusalLive"], Value::Null, "{announced}");
    assert_eq!(
        announced["describedBy"], announced["refusalId"],
        "the half that is missing is not described by the refusal: {announced}"
    );
    // The description goes when the sentence does: finishing the answer
    // clears both, so nothing reads out a refusal that is no longer true.
    click_control(&desk.tab, &format!("{form} input[name=outcome]"));
    wait_for_js_true(
        &desk.tab,
        &format!(
            "!document.querySelector('{form} {}')",
            ui::error_refusal("incomplete")
        ),
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!("document.querySelectorAll('{form} [aria-describedby]').length")
        ),
        0,
        "a cleared refusal is still described"
    );
    // Nothing was sent, and the reply the operator wrote is still theirs to
    // finish.
    assert_eq!(
        js_value(&desk.tab, "window.__posts.length"),
        0,
        "an incomplete answer posted anyway: {}",
        js_value(&desk.tab, "JSON.stringify(window.__posts)")
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!("document.querySelector('{form} textarea[name=reply]').value")
        ),
        "Assign the seat, but bill it to the platform budget."
    );
    assert_eq!(
        js_value(
            &desk.tab,
            "document.querySelector('__CURRENT__').dataset.item"
        ),
        desk.ids[0].as_str(),
        "a refused composer advanced the deck"
    );

    // The other half of the same rule, on the next card: a verdict with no
    // words is refused the same way, and the WORDS clear it as they are
    // typed. The sentence has to go when the answer becomes complete, not
    // when the operator clicks again into a refusal that is no longer true.
    // The cursor is on the verdict the last step picked, and a key pressed
    // into a control is that control's (WEB-23): the card is focused first,
    // which is what clicking anywhere on it does.
    assert_eq!(
        js_value(
            &desk.tab,
            "(() => { document.querySelector('__CURRENT_CARD__').focus(); \
             return document.activeElement === document.querySelector('__CURRENT_CARD__'); })()"
        ),
        true,
        "the card did not take the focus back"
    );
    desk.tab.press_key("s").expect("skip to the next card");
    wait_for_js_true(
        &desk.tab,
        &format!(
            "document.querySelector('__CURRENT__').dataset.item === \"{}\"",
            desk.ids[1]
        ),
    );
    open_custom_answer(&desk.tab, form);
    click_control(&desk.tab, &format!("{form} input[name=outcome]"));
    click_control(&desk.tab, &format!("{form} button.record"));
    wait_for_js_true(
        &desk.tab,
        &format!(
            "Boolean(document.querySelector('{form} {}'))",
            ui::error_refusal("incomplete")
        ),
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!(
                "document.activeElement === document.querySelector('{form} textarea[name=reply]')"
            )
        ),
        true,
        "the cursor is not on the words that are missing"
    );
    desk.tab
        .press_key("N")
        .expect("type one word of the answer");
    wait_for_js_true(
        &desk.tab,
        &format!(
            "!document.querySelector('{form} {}')",
            ui::error_refusal("incomplete")
        ),
    );
    assert_eq!(
        js_value(&desk.tab, "window.__posts.length"),
        0,
        "typing posted an answer: {}",
        js_value(&desk.tab, "JSON.stringify(window.__posts)")
    );
    let open = desk.fixture.ok_json(
        &desk.fixture.main,
        &["attention", "list", "--status", "open", "--json"],
    );
    assert_eq!(open.as_array().expect("the open rows").len(), 3, "{open}");
    assert!(
        open.as_array()
            .unwrap()
            .iter()
            .all(|row| row["decision"].is_null()),
        "the board recorded a decision the page refused to post: {open}"
    );
}

/// A6 (SPA-22, SPA-21) — the item was settled by another lane while the card
/// was on screen, and the store is the one that says so.
///
/// The two shipped refusal cases stub a `409` at `window.fetch`, which
/// measures the page's handling of a refusal and nothing about the sentence
/// the board actually writes. Here nothing is stubbed: `attention resolve`
/// runs through the binary as the raiser, the browser then posts the answer
/// it was already holding, and `Store::resolve_attention_with_authorization`
/// refuses it. What is asserted is the store's own sentence, character for
/// character, on the card's board-refusal node.
///
/// The note is typed FIRST on purpose. A draft is what holds an arriving
/// projection (`answerInProgress`), so the deck goes on showing the card the
/// board has already moved past — which is the only way a real board refusal
/// can be reached from a real browser at all.
#[test]
fn a_card_another_lane_resolved_is_refused_by_the_board_in_real_chrome() {
    let desk = deck_desk("serve-deck-board-gone", "DECKGONE");
    let id = desk.ids[0].clone();
    let form = ui::CURRENT_DECIDE;
    let recommended = format!("{form} {}", ui::RECOMMENDED_CHOICE);

    let note = desk
        .tab
        .wait_for_element(&format!("{form} {}", ui::DECK_NOTE))
        .expect("the note field");
    note.click().expect("focus the note");
    note.type_into("hold it").expect("type the note");
    wait_for_js_true(
        &desk.tab,
        &format!("document.querySelector('{form} __DECK_NOTE__').value === 'hold it'"),
    );

    // Another lane settles it through the binary. The raiser may resolve its
    // own item, so this is a write the board accepts and not a refusal of
    // its own.
    desk.fixture.ok_json(
        &desk.fixture.main,
        &[
            "attention",
            "resolve",
            &id,
            "--as",
            "codex@driver",
            "--choice",
            "keep-parked",
            "--json",
        ],
    );
    let rows = wait_for_notice_rows(&desk.tab, 1, "the other lane's resolution");
    eprintln!("notice while the card is held: {rows:?}");

    click_control(&desk.tab, &recommended);
    let refused = format!("{form} {}", ui::refusal("board"));
    wait_for_js_true(
        &desk.tab,
        &format!("Boolean(document.querySelector('{refused}'))"),
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!("document.querySelector('{refused}').textContent")
        ),
        format!(
            "attention {id} was already resolved by codex@driver \
             — it is history, not a queue entry"
        ),
        "the card is not carrying the store's own sentence"
    );

    let measured = measure(
        &desk.tab,
        &format!(
            "(() => {{ const card = document.querySelector('__CARD__[data-item=\"{id}\"]'); \
             const controls = [...card.querySelectorAll('.choice, .record')]; \
             return JSON.stringify({{ \
             current: document.querySelector('__CURRENT__').dataset.item, \
             slot: [...document.querySelectorAll('__CARD__')] \
               .findIndex(row => row.dataset.item === '{id}'), \
             controls: controls.length, \
             enabled: controls.every(control => !control.disabled), \
             state: card.dataset.state ?? null, \
             busy: card.getAttribute('aria-busy'), \
             count: document.querySelector('__DECK_COUNT__').textContent, \
             receipts: document.querySelectorAll('__RECEIPT__').length, \
             history: document.querySelectorAll('__HISTORY_RECEIPT__').length, \
             note: card.querySelector('__DECK_NOTE__').value }}); }})()"
        ),
        "the card the board refused",
    );
    eprintln!("refused by the board: {measured}");
    assert_eq!(measured["current"], id.as_str(), "{measured}");
    assert_eq!(
        measured["slot"], 0,
        "the refused card lost its place: {measured}"
    );
    assert!(
        measured["controls"].as_i64().unwrap_or_default() > 1,
        "{measured}"
    );
    assert_eq!(
        measured["enabled"], true,
        "a refused card cannot be answered at all: {measured}"
    );
    assert_eq!(measured["state"], Value::Null, "{measured}");
    assert_eq!(measured["busy"], Value::Null, "{measured}");
    assert_eq!(
        measured["count"], "3",
        "the deck's remaining count moved on a decision nothing recorded: {measured}"
    );
    assert_eq!(measured["receipts"], 0, "{measured}");
    assert_eq!(measured["history"], 0, "{measured}");
    assert_eq!(
        measured["note"], "hold it",
        "the refusal took the operator's words with it: {measured}"
    );

    // The board is where it was before the click: the other lane's decision,
    // and no second one written over it.
    let settled = settled_row(&desk.fixture, &id);
    assert_eq!(settled["decision"]["choice"], "keep-parked", "{settled}");
    assert_eq!(settled["decision"]["by"], "codex@driver", "{settled}");
    let open = desk.fixture.ok_json(
        &desk.fixture.main,
        &["attention", "list", "--status", "open", "--json"],
    );
    assert_eq!(open.as_array().expect("the open rows").len(), 2, "{open}");
}

/// A7 (SPA-22, SPA-21) — the authored choices were rewritten underneath, and
/// the refusal names the key that is gone.
///
/// The same rule `a_reply_naming_a_choice_the_row_no_longer_carries_is_refused_by_name_over_http`
/// drives over HTTP, driven here from the card a person is actually looking
/// at: the rewrite lands through `attention update`, the stale key is
/// clicked, and the sentence `rust/model.rs`'s composer writes is on the
/// card. Then the held projection lands and the answers on screen are the
/// ones that now exist — and one of those records.
///
/// A picked verdict is the hold, rather than a typed note: clicking an
/// authored choice clears the verdict, so the page stops answering the
/// moment the refusal arrives and the projection it was holding is applied.
/// A note would hold it for ever and the second half of A7 could not run.
#[test]
fn a_stale_choice_is_refused_by_name_and_the_rewritten_keys_record_in_real_chrome() {
    let desk = deck_desk("serve-deck-stale-choice", "DECKSTALE");
    let id = desk.ids[0].clone();
    let form = ui::CURRENT_DECIDE;

    open_custom_answer(&desk.tab, form);
    click_control(&desk.tab, &format!("{form} input[name=outcome]"));
    wait_for_js_true(
        &desk.tab,
        &format!("document.querySelector('{form} input[name=outcome]').checked"),
    );

    desk.fixture.ok_json(
        &desk.fixture.main,
        &[
            "attention",
            "update",
            &id,
            "--as",
            "codex@driver",
            "--question",
            "Which seat pays for the hax login: the platform budget, or the lane that needs it?",
            "--context",
            "Rewritten by the raiser while this card was open, which is the whole point of the case.",
            "--choice",
            "go=Charge it to the platform budget|approve",
            "--consequence",
            "go=The seat is bought today and the adapter's live receipt is taken this week.",
            "--choice",
            "wait=Wait for a seat to free up|defer",
            "--consequence",
            "wait=Nothing is bought and the receipt waits on somebody else's renewal.",
            "--recommend",
            "go",
            "--json",
        ],
    );
    let rows = wait_for_notice_rows(&desk.tab, 1, "the other lane's rewrite");
    eprintln!("notice while the card is held: {rows:?}");

    // The key the card is still showing, which the row no longer carries.
    click_control(
        &desk.tab,
        &format!("{form} [data-testid=deck-choice-keep-parked]"),
    );
    let refused = format!("__CARD__[data-item=\"{id}\"] {}", ui::refusal("board"));
    wait_for_js_true(
        &desk.tab,
        &format!("Boolean(document.querySelector('{refused}'))"),
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!("document.querySelector('{refused}').textContent")
        ),
        format!("attention {id} has no choice keep-parked; its choices are go, wait"),
        "the refusal does not name the key the row no longer carries"
    );
    let open = desk.fixture.ok_json(
        &desk.fixture.main,
        &["attention", "list", "--status", "open", "--json"],
    );
    assert_eq!(open.as_array().expect("the open rows").len(), 3, "{open}");
    assert!(
        open.as_array()
            .unwrap()
            .iter()
            .all(|row| row["decision"].is_null()),
        "a refused key settled the row anyway: {open}"
    );

    // The refreshed card: the keys that now exist, and the stale one gone.
    wait_for_js_true(
        &desk.tab,
        &format!(
            "(() => {{ const card = document.querySelector('__CARD__[data-item=\"{id}\"]'); \
             return Boolean(card) \
             && Boolean(card.querySelector('[data-testid=deck-choice-go]')) \
             && Boolean(card.querySelector('[data-testid=deck-choice-wait]')) \
             && !card.querySelector('[data-testid=deck-choice-keep-parked]'); }})()"
        ),
    );
    assert_eq!(
        js_value(
            &desk.tab,
            &format!(
                "JSON.stringify([...document.querySelectorAll('__CARD__[data-item=\"{id}\"] \
                 __DECK_CHOICES__')].map(button => button.value))"
            )
        ),
        "[\"go\",\"wait\"]",
        "the refreshed card is not showing the choices the row now carries"
    );

    // ...and one of them records, so what was measured is the key and not a
    // write path the refusal broke.
    click_control(&desk.tab, &format!("{form} [data-testid=deck-choice-go]"));
    assert_receipt(&desk.tab, &id, "Charge it to the platform budget");
    let settled = settled_row(&desk.fixture, &id);
    assert_eq!(settled["decision"]["choice"], "go", "{settled}");
    assert_eq!(settled["decision"]["outcome"], "approve", "{settled}");
    assert_eq!(settled["decision"]["by"], "geoyws", "{settled}");
}

/// SPA-31 — one quiet keyboard line, and the digits live on the buttons.
///
/// The shipped proof was `one_quiet_keys_line_carries_no_kbd_badges_unit`
/// over the bytes the server used to render, which the SPA retires. This is
/// the same rule read off the MOUNTED deck: one line, in the quiet register,
/// naming each key beside what it does; every answer carrying its own digit
/// in a node of its own; and no `kbd` badge cluster competing with the
/// answers anywhere on the page.
#[test]
fn one_quiet_keys_line_names_the_digits_on_the_answers_in_real_chrome() {
    let desk = deck_desk("serve-deck-keys-line", "DECKKEYS");
    let quiet = token(&desk.tab, "--overlay");

    let measured = measure(
        &desk.tab,
        "(() => { const lines = [...document.querySelectorAll('__DECK_KEYS__')]; \
         const line = lines[0]; const style = getComputedStyle(line); \
         const probe = document.createElement('span'); \
         probe.style.fontFamily = 'var(--mono)'; document.body.append(probe); \
         const mono = getComputedStyle(probe).fontFamily; probe.remove(); \
         const card = document.querySelector('__CURRENT_CARD__'); \
         const buttons = [...card.querySelectorAll('__DECK_CHOICES__')]; \
         return JSON.stringify({ \
         lines: lines.length, \
         text: line.textContent, \
         inCard: Boolean(line.closest('__CARD__')), \
         color: style.color, \
         fontFamily: style.fontFamily, \
         mono, \
         size: parseFloat(style.fontSize), \
         bodySize: parseFloat(getComputedStyle(document.body).fontSize), \
         digits: buttons.map(button => \
           [...button.querySelectorAll('__DECK_DIGIT__')].map(node => node.textContent)), \
         kbd: document.querySelectorAll('kbd').length}); })()",
        "the deck's keyboard line",
    );
    eprintln!("keys: {measured}");
    assert_eq!(
        measured["lines"], 1,
        "the deck renders more than one keyboard hint line: {measured}"
    );
    assert_eq!(
        measured["inCard"], false,
        "the keyboard line is inside a card, so every card repeats it: {measured}"
    );
    let text = measured["text"].as_str().expect("the line's text");
    for named in ["1–4 answer", "s skip", "u undo", "c own"] {
        assert!(
            text.contains(named),
            "the keyboard line does not name {named:?}: {measured}"
        );
    }
    assert_eq!(
        measured["color"],
        quiet.as_str(),
        "the keyboard line is not in the quiet register: {measured}"
    );
    assert_eq!(
        measured["fontFamily"], measured["mono"],
        "the keyboard line is not in the mono stack: {measured}"
    );
    assert!(
        measured["size"].as_f64().unwrap_or_default()
            < measured["bodySize"].as_f64().unwrap_or_default(),
        "the keyboard line is not quieter than the page's own text: {measured}"
    );
    assert_eq!(
        measured["kbd"], 0,
        "a key-badge cluster is competing with the answers: {measured}"
    );
    // Each answer carries ITS digit, in its own node, in the order the
    // keyboard map promises: `1` is the recommendation, and nothing shares.
    assert_eq!(
        measured["digits"],
        json!([["1"], ["2"], ["3"]]),
        "the digits are not one per answer, on the answer: {measured}"
    );
}

/// WEB-59 — and each channel says only its own thing.
///
/// Two live regions with two jobs: the connection line says what the socket
/// is and nothing else, and what arrived is a log entry. The line's whole
/// history is recorded as it changes, because a single reading afterwards
/// would miss the one word that should never have been there.
#[test]
fn the_live_line_and_the_toast_log_say_only_their_own_thing_in_real_chrome() {
    let desk = deck_desk("serve-deck-channels", "DECKSAYS");
    wait_for_live_status(&desk.tab, "live", "the deck's first connect");
    assert_eq!(
        js_value(
            &desk.tab,
            "(() => { const line = document.querySelector('__LIVE__'); \
             window.__words = [line.textContent]; \
             new MutationObserver(() => { const now = line.textContent; \
             if (window.__words[window.__words.length - 1] !== now) window.__words.push(now); }) \
             .observe(line, {subtree: true, childList: true, characterData: true}); \
             return true; })()"
        ),
        true
    );

    // A decision of our own, then somebody else's change: the two things
    // that ever wrote to these regions.
    click_control(
        &desk.tab,
        &format!("{} {}", ui::CURRENT_DECIDE, ui::RECOMMENDED_CHOICE),
    );
    wait_for_js_true(
        &desk.tab,
        "Boolean(document.querySelector('__HISTORY_RECEIPT__'))",
    );
    wait_for_projection_swap(&desk.tab);
    file_task(&desk.fixture, "Another lane filed its own task", "t-says");
    let rows = wait_for_notice_rows(&desk.tab, 1, "the other lane's change");
    assert!(
        rows[0].contains("Another lane filed its own task"),
        "{rows:?}"
    );

    let measured = measure(
        &desk.tab,
        // The status channel is whatever element HAS that role: the deck's
        // connection line is an `<output>`, whose role is `status` without
        // the attribute being written, and `/all` writes the attribute on a
        // span. Both are one status region; what is asserted is that there
        // is one of each channel and neither doubles as the other.
        "(() => { const STATUS = '[role=status], output:not([role])'; \
         const line = document.querySelector(STATUS); \
         const log = document.querySelector('[role=log]'); \
         return JSON.stringify({words: window.__words, line: line.textContent, \
         statuses: document.querySelectorAll(STATUS).length, \
         logs: document.querySelectorAll('[role=log]').length, \
         logIsStatus: log.matches(STATUS), \
         lineIsLog: line.matches('[role=log]'), \
         noticeInLog: [...document.querySelectorAll('__NOTICE__')] \
           .every(row => row.closest('[role=log]') === log), \
         receiptOutsideStatus: !line.textContent.includes('Decided')}); })()",
        "the two channels",
    );
    eprintln!("channels: {measured}");
    let words = measured["words"].as_array().expect("the line's history");
    assert!(
        words.iter().all(|word| matches!(
            word.as_str().unwrap_or_default(),
            "connecting" | "live" | "reconnecting" | "sending"
        )),
        "the connection line said something that is not the socket's state: {measured}"
    );
    assert!(
        words.iter().any(|word| word == "sending"),
        "the line never said what the click was doing, so nothing was observed: {measured}"
    );
    assert_eq!(measured["statuses"], 1, "{measured}");
    assert_eq!(measured["logs"], 1, "{measured}");
    assert_eq!(measured["logIsStatus"], false, "{measured}");
    assert_eq!(measured["lineIsLog"], false, "{measured}");
    assert_eq!(
        measured["noticeInLog"], true,
        "a notice landed outside the log: {measured}"
    );
    assert_eq!(
        measured["receiptOutsideStatus"], true,
        "the connection line is reporting a decision: {measured}"
    );
}

/// WEB-17 — the pressed answer says what it is doing on its own fill.
///
/// A disabled grey button is the one control that cannot report its own
/// refusal, so nothing is disabled: the pressed answer keeps its fill, says
/// `Sending…` on it, and the OTHER answers step back instead. Read inside
/// the window a held POST keeps open, which is where a slow link lives.
#[test]
fn the_pressed_answer_says_sending_on_its_own_fill_in_real_chrome() {
    let desk = deck_desk("serve-deck-sending-fill", "DECKSEND");
    let green = token(&desk.tab, "--green");
    let pressed = format!("{} {}", ui::CURRENT_DECIDE, ui::RECOMMENDED_CHOICE);
    let before = js_value(
        &desk.tab,
        &format!("getComputedStyle(document.querySelector('{pressed}')).backgroundColor"),
    );
    assert_eq!(before, green.as_str(), "the recommendation is not filled");

    assert_eq!(js_value(&desk.tab, HOLD_THE_POST), true);
    click_control(&desk.tab, &pressed);
    wait_for_js_true(&desk.tab, "typeof window.__answer === 'function'");
    wait_for_js_true(
        &desk.tab,
        "Boolean(document.querySelector('__SENT_CARD__ [data-pressed]'))",
    );

    let measured = measure(
        &desk.tab,
        "(() => { const card = document.querySelector('__SENT_CARD__'); \
         const sent = card.querySelector('[data-pressed]'); \
         const others = [...card.querySelectorAll('.choice:not([data-pressed]), \
         .record:not([data-pressed])')]; \
         return JSON.stringify({text: sent.textContent, \
         background: getComputedStyle(sent).backgroundColor, \
         disabled: sent.disabled, opacity: parseFloat(getComputedStyle(sent).opacity), \
         others: others.map(el => parseFloat(getComputedStyle(el).opacity)), \
         busy: card.getAttribute('aria-busy')}); })()",
        "the pressed answer",
    );
    eprintln!("sending: {measured}");
    assert_eq!(measured["text"], "Sending…", "{measured}");
    assert_eq!(
        measured["background"], before,
        "the pressed answer changed fill instead of speaking on its own: {measured}"
    );
    assert_eq!(
        measured["disabled"], false,
        "the pressed answer was disabled, so it can no longer report a refusal: {measured}"
    );
    assert_eq!(measured["opacity"].as_f64(), Some(1.0), "{measured}");
    assert_eq!(measured["busy"], "true", "{measured}");
    let others = measured["others"].as_array().expect("the other answers");
    assert!(others.len() >= 2, "{measured}");
    for opacity in others {
        assert!(
            opacity.as_f64().unwrap_or(1.0) < 1.0,
            "an answer that was not pressed did not step back: {measured}"
        );
    }
}

/// WEB-18 — the receipt encodes its outcome.
///
/// The decision just made reads as a row with a 3px rule in the hue of the
/// verdict it recorded, and it is the only coloured rule in the history: a
/// second one would make the colour decoration rather than the one thing a
/// reader needs from a decision already made.
#[test]
fn the_receipt_lands_with_its_outcome_rule_in_real_chrome() {
    let desk = deck_desk("serve-deck-receipt-rule", "DECKRULE");
    let green = token(&desk.tab, "--green");
    let surface1 = token(&desk.tab, "--surface1");
    // The recommendation of this fixture is the `approve` choice, so the row
    // it lands has to carry the approve hue and nothing else may carry one.
    hold_projection(&desk.tab);
    click_control(
        &desk.tab,
        &format!("{} {}", ui::CURRENT_DECIDE, ui::RECOMMENDED_CHOICE),
    );
    wait_for_js_true(
        &desk.tab,
        "document.querySelectorAll('__HISTORY__ __RECEIPT__').length === 1",
    );
    let measured = measure(
        &desk.tab,
        "(() => { const rows = [...document.querySelectorAll('__HISTORY__ p')]; \
         return JSON.stringify({rows: rows.map(row => { const style = getComputedStyle(row); \
         return {classes: row.className, width: parseFloat(style.borderLeftWidth) || 0, \
         color: style.borderLeftColor}; })}); })()",
        "the landed receipt",
    );
    eprintln!("receipt: {measured}");
    let rows = measured["rows"].as_array().expect("the history rows");
    let ruled = rows
        .iter()
        .filter(|row| row["width"].as_f64().unwrap_or(0.0) > 0.0)
        .collect::<Vec<_>>();
    assert_eq!(
        ruled.len(),
        1,
        "the history carries more than one left rule: {measured}"
    );
    assert!(
        ruled[0]["classes"]
            .as_str()
            .unwrap_or_default()
            .contains("outcome-approve"),
        "the ruled row is not the receipt just recorded: {measured}"
    );
    assert_eq!(
        ruled[0]["width"].as_f64().unwrap_or(0.0),
        3.0,
        "the receipt's rule is not 3px: {measured}"
    );
    assert_eq!(
        ruled[0]["color"],
        green.as_str(),
        "the receipt's rule is not the hue of the outcome it recorded: {measured}"
    );
    assert_ne!(
        ruled[0]["color"],
        surface1.as_str(),
        "the receipt fell back to the colourless rule: {measured}"
    );
}

/// A board read as rows: one task in each status the board groups by, one of
/// them `P0`, plus a verified release so `/deployments` renders its table,
/// plus one open ask so `/task/{project}/{id}` renders its own row list.
///
/// The ask is the task detail's rows, not the deck's: `/task` is the mounted
/// application since `t-bf255880` wave 1, and the row shape it renders is
/// held by the same sweep as every other read page rather than by a
/// server-rendered-bytes assertion that can no longer reach it.
fn rows_fixture(label: &str, board: &str) -> (Fixture, String) {
    let fixture = Fixture::new(label);
    fixture.ok_json(&fixture.main, &["init", "--name", board, "--json"]);
    fixture.ok_json(
        &fixture.main,
        &["tag", "add", "rows", "--as", "fixture-agent", "--json"],
    );
    for (id, title, status, priority) in [
        (
            "t-rows-todo",
            "The row that is waiting to start",
            "todo",
            "P0",
        ),
        (
            "t-rows-doing",
            "The row somebody is holding",
            "in_progress",
            "P1",
        ),
        (
            "t-rows-blocked",
            "The row that cannot move",
            "blocked",
            "P1",
        ),
        (
            "t-rows-review",
            "The row waiting on a reader",
            "review",
            "P1",
        ),
        ("t-rows-done", "The row that shipped", "done", "P2"),
    ] {
        fixture.ok_json(
            &fixture.main,
            &[
                "task",
                "add",
                title,
                "--id",
                id,
                "--type",
                "task",
                "--status",
                status,
                "--priority",
                priority,
                "--tag",
                "rows",
                "--as",
                "fixture-agent",
                "--json",
            ],
        );
    }
    let deployment = fixture.ok_json(
        &fixture.main,
        &[
            "deploy",
            "start",
            "--repo",
            "geoyws/kanban-rows",
            "--commit",
            "dddddddddddddddddddddddddddddddddddddddd",
            "--tier",
            "@_bd",
            "--environment",
            "rows-fixture",
            "--host",
            "geoywsMBP",
            "--url",
            "http://127.0.0.1:14400",
            "--task",
            "t-rows-done",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    let deployment_id = deployment["id"]
        .as_str()
        .expect("the deployment")
        .to_owned();
    fixture.ok_json(
        &fixture.main,
        &[
            "deploy",
            "finish",
            &deployment_id,
            "--token",
            deployment["capabilityToken"]
                .as_str()
                .expect("the capability token"),
            "--result",
            "succeeded",
            "--phase",
            "verification",
            "--served-commit",
            "dddddddddddddddddddddddddddddddddddddddd",
            "--receipt",
            "The rows fixture served exact commit dddddddddddd.",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "attention",
            "raise",
            "Please review the row somebody is holding.",
            "--task",
            "t-rows-doing",
            "--kind",
            "decision",
            "--as",
            "fixture-agent",
            "--json",
        ],
    );
    (fixture, deployment_id)
}

/// Every `th` and `td` on the page, with each drawn edge named.
const TABLE_SWEEP: &str = r#"(() => {
  const sides = ['Top', 'Right', 'Bottom', 'Left'];
  const cells = [...document.querySelectorAll('th, td')].filter(cell => cell.checkVisibility());
  return JSON.stringify({
    cells: cells.map(cell => {
      const style = getComputedStyle(cell);
      const drawn = sides
        .map(side => ({
          side,
          width: parseFloat(style[`border${side}Width`]) || 0,
          color: style[`border${side}Color`],
          style: style[`border${side}Style`],
        }))
        .filter(edge => edge.width > 0 && edge.style !== 'none');
      return {
        where: `${cell.tagName.toLowerCase()}.${cell.className}`,
        total: drawn.reduce((sum, edge) => sum + edge.width, 0),
        drawn,
        numeric: cell.classList.contains('n'),
        align: style.textAlign,
        family: style.fontFamily,
      };
    }),
  });
})()"#;

/// WEB-43 — the tables lose their borders and keep the hairline, and it
/// holds in the browser.
///
/// The unit layer reads the stylesheet; this reads what Chrome computed on
/// the two table pages with rows actually seeded under them. A cell either
/// draws the one row separator or draws nothing, and a numeric column is
/// right-aligned mono so a column of counts reads as a column.
#[test]
fn read_tables_are_borderless_but_for_the_hairline_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, _deployment) = rows_fixture("serve-rows-tables", "ROWSTABLE");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = opened_tab(&chrome, "rows table tab");
    let surface0 = {
        go(&tab, &origin, "/boards");
        token(&tab, "--surface0")
    };
    assert_eq!(
        surface0, "rgb(49, 50, 68)",
        "the hairline token moved, so the figure this case names is stale"
    );
    for route in ["/boards", "/deployments"] {
        go(&tab, &origin, route);
        // `/deployments` is mounted since `t-bf255880` wave 1: measuring at
        // the shell would measure a page with no cells in it.
        if route == "/deployments" {
            wait_for_mounted_page(&tab, "[data-testid=deployments-current]");
        }
        let measured = measure(&tab, TABLE_SWEEP, "the table sweep");
        let cells = measured["cells"].as_array().expect("the cells");
        assert!(
            cells.len() >= 7,
            "{route} rendered {} cells, so no table was measured: {measured}",
            cells.len()
        );
        let mut hairlines = 0;
        let mut numeric = 0;
        for cell in cells {
            let total = cell["total"].as_f64().unwrap_or(0.0);
            assert!(
                total == 0.0 || total == 1.0,
                "{route}: {} draws {total}px of border: {cell}",
                cell["where"]
            );
            if total == 1.0 {
                hairlines += 1;
                let drawn = cell["drawn"].as_array().expect("the drawn edges");
                assert_eq!(drawn.len(), 1, "{route}: {cell}");
                assert_eq!(
                    drawn[0]["side"], "Bottom",
                    "{route}: the one hairline is not the row separator: {cell}"
                );
                assert_eq!(
                    drawn[0]["color"],
                    surface0.as_str(),
                    "{route}: the row separator is not the hairline token: {cell}"
                );
            }
            if cell["numeric"] == Value::Bool(true) {
                numeric += 1;
                assert_eq!(
                    cell["align"], "right",
                    "{route}: a numeric cell is not right-aligned: {cell}"
                );
                let family = cell["family"].as_str().expect("the cell's family");
                assert!(
                    family.contains("ui-monospace") && family.contains("monospace"),
                    "{route}: a numeric cell is not set in the mono stack: {cell}"
                );
            }
        }
        assert!(
            hairlines > 0,
            "{route} drew no row separator at all: {measured}"
        );
        if route == "/boards" {
            assert!(
                numeric >= 6,
                "/boards measured {numeric} numeric cells, so the count columns went unproved: \
                 {measured}"
            );
        }
    }
}

/// What a read page is made of: its rows, its badges and its priority.
const ROW_SWEEP: &str = r#"(() => {
  const rows = [...document.querySelectorAll('ul.rows>li, ul.children>li')];
  const retired = [...document.querySelectorAll('span.tag, span.kind, span.type, span.lane')];
  const stated = [...document.querySelectorAll('[class*=status-]')];
  const p0 = document.querySelector('span.priority.priority-p0');
  const p0Style = p0 ? getComputedStyle(p0) : null;
  return JSON.stringify({
    rows: rows.map(row => {
      const lead = row.firstElementChild;
      const after = lead ? lead.nextElementSibling : null;
      return {
        lead: lead ? lead.tagName.toLowerCase() : null,
        leadClass: lead ? lead.className : null,
        leadText: lead ? lead.textContent : null,
        href: lead ? lead.getAttribute('href') : null,
        metas: row.querySelectorAll('.meta').length,
        after: after ? `${after.tagName.toLowerCase()}.${after.className}` : null,
        meta: (row.querySelector('.meta') || {textContent: ''}).textContent,
      };
    }),
    retired: retired.map(el => `${el.tagName.toLowerCase()}.${el.className}`),
    stated: stated.map(el => `${el.tagName.toLowerCase()}|${el.className}`),
    p0: p0Style
      ? {
          text: p0.textContent,
          family: p0Style.fontFamily,
          color: p0Style.color,
          background: p0Style.backgroundColor,
          radius: p0Style.borderRadius,
        }
      : null,
  });
})()"#;

/// A11 — read pages are rows, with one pill and a mono priority (WEB-40,
/// WEB-41, WEB-42, WEB-43).
///
/// The whole acceptance in one measurement, on a board carrying one task in
/// each status the board groups by and one of them `P0`: each row is a title
/// and one sentence, status is the only pill and the only badge, the `P0`
/// priority is red mono text rather than a pill, and the tables draw the one
/// hairline.
///
/// The task detail is swept here too since `t-bf255880` wave 1 mounted it:
/// its open-attention list is the one row list that leads with a title
/// element rather than an anchor, and the bytes assertion that used to hold
/// it (`serve::tests::web_rows_child_process`) can no longer reach a route
/// that answers the shell.
#[test]
fn read_pages_are_rows_with_one_pill_and_a_mono_priority_in_real_chrome() {
    browser_loopback_reservation_supported()
        .expect("reserve loopback port for browser-backed server tests");
    let (fixture, _deployment) = rows_fixture("serve-rows-a11", "ROWSA11");
    let server = spawn_server_with_actor_header(&fixture, Some("X-Auth-Request-Email"));
    let origin = server.origin();
    let chrome = launch_browser(chrome_binary());
    let tab = opened_tab(&chrome, "rows acceptance tab");
    let mut measured_rows = 0;
    let mut measured_pills = 0;
    // `/task/{project}/{id}` last: it is the row list whose lead is a title
    // element, and the only one of the four with an anti-vacuity floor of
    // its own below.
    let task_route = "/task/ROWSA11/t-rows-doing";
    let mut task_rows = 0;
    let mut task_titles = Vec::new();
    for route in ["/board/ROWSA11", "/boards", "/deployments", task_route] {
        go(&tab, &origin, route);
        // Both are mounted since `t-bf255880` wave 1, so the measurement
        // waits for the page the bundle renders rather than for the shell.
        if route == "/deployments" {
            wait_for_mounted_page(&tab, "[data-testid=deployments-current]");
        }
        if route == task_route {
            wait_for_mounted_page(&tab, "[data-task-attention]");
        }
        let measured = measure(&tab, ROW_SWEEP, "the row sweep");
        eprintln!("{route}: {measured}");
        for row in measured["rows"].as_array().expect("the rows") {
            measured_rows += 1;
            if route == task_route {
                task_rows += 1;
                task_titles.push(row["leadText"].as_str().unwrap_or_default().to_owned());
            }
            let lead = row["lead"].as_str().unwrap_or_default();
            let lead_class = row["leadClass"].as_str().unwrap_or_default();
            assert!(
                lead == "a" || lead_class.split_whitespace().any(|part| part == "title"),
                "{route}: a row leads with <{lead}> rather than its title: {row}"
            );
            if lead == "a" {
                assert!(
                    row["href"]
                        .as_str()
                        .is_some_and(|href| href.starts_with('/')),
                    "{route}: a row's title is an anchor that opens no page: {row}"
                );
            }
            assert_eq!(
                row["metas"].as_i64(),
                Some(1),
                "{route}: a row carries more or less than one sentence: {row}"
            );
            assert_eq!(
                row["after"]
                    .as_str()
                    .map(|after| after.starts_with("p.meta")),
                Some(true),
                "{route}: a row's title is not followed by its sentence: {row}"
            );
            assert!(
                !row["meta"].as_str().unwrap_or_default().contains(" · "),
                "{route}: a row's sentence reads as a chain: {row}"
            );
        }
        assert_eq!(
            measured["retired"]
                .as_array()
                .expect("the retired badges")
                .len(),
            0,
            "{route} still renders a second badge class: {measured}"
        );
        for stated in measured["stated"].as_array().expect("the status carriers") {
            let stated = stated.as_str().expect("a status carrier");
            let (tag, classes) = stated.split_once('|').expect("tag and classes");
            assert_eq!(
                tag, "span",
                "{route}: a status is carried by <{tag}> rather than a pill span: {stated}"
            );
            let mut parts = classes.split_whitespace();
            assert_eq!(
                parts.next(),
                Some("pill"),
                "{route}: a status is not the one pill: {stated}"
            );
            let modifier = parts.next().unwrap_or_default();
            assert!(
                modifier.starts_with("status-"),
                "{route}: a pill carries {modifier} beside its status: {stated}"
            );
            assert_eq!(
                parts.next(),
                None,
                "{route}: a pill carries a third class: {stated}"
            );
            measured_pills += 1;
        }
        if route == "/board/ROWSA11" {
            let p0 = &measured["p0"];
            assert!(
                !p0.is_null(),
                "the board rendered no P0 priority to measure: {measured}"
            );
            assert_eq!(p0["text"], "P0", "{measured}");
            let family = p0["family"].as_str().expect("the priority's family");
            assert!(
                family.contains("ui-monospace") && family.contains("monospace"),
                "the priority is not set in the mono stack: {measured}"
            );
            assert_eq!(
                p0["color"], "rgb(243, 139, 168)",
                "P0 is not in the red the design reserves for it: {measured}"
            );
            assert_eq!(
                p0["background"], "rgba(0, 0, 0, 0)",
                "the priority is filled, so it is a pill again: {measured}"
            );
            assert_eq!(
                p0["radius"], "0px",
                "the priority is rounded, so it is a pill again: {measured}"
            );
        }
        let tables = measure(&tab, TABLE_SWEEP, "the table sweep");
        for cell in tables["cells"].as_array().expect("the cells") {
            let total = cell["total"].as_f64().unwrap_or(0.0);
            assert!(
                total == 0.0 || total == 1.0,
                "{route}: {} draws {total}px of border: {cell}",
                cell["where"]
            );
            if total == 1.0 {
                let drawn = cell["drawn"].as_array().expect("the drawn edges");
                assert_eq!(drawn[0]["side"], "Bottom", "{route}: {cell}");
                assert_eq!(drawn[0]["color"], "rgb(49, 50, 68)", "{route}: {cell}");
            }
        }
    }
    assert!(
        measured_rows >= 5,
        "the acceptance measured only {measured_rows} rows"
    );
    // The floor the server-rendered sweep used to carry: the task detail's
    // row list is the one it could still measure, and it moved here with
    // the route. A sweep that found no row on it would pass while proving
    // nothing about the page that renders them.
    assert!(
        task_rows >= 1,
        "the task detail rendered no open-attention row, so its rows went unmeasured"
    );
    assert!(
        task_titles
            .iter()
            .any(|title| title.starts_with("Please review ")),
        "the task detail's row does not lead with the ask it was seeded with: {task_titles:?}"
    );
    assert!(
        measured_pills >= 5,
        "the acceptance measured only {measured_pills} pills"
    );
}

// -------------------------------------------------- model-restricted tasks

/// The refusal a restricted task gives, and the claim that gets through.
///
/// George's ask, in his words: "only a subset of models, or one model, can
/// claim this task. Blender must only be used by Astra." What makes that
/// scheduling rather than documentation is that the refusal happens on the
/// claim path, beside `driver_only` and `assignee` — so this also pins where
/// in the order it sits: a driver-only restricted row refuses driver-only
/// first, and an assigned restricted row refuses the model first.
#[test]
fn model_restricted_task_refuses_a_claim_without_or_outside_its_allow_list() {
    let fixture = Fixture::new("model-claim");
    fixture.ok_json(&fixture.main, &["init", "--name", "MODEL", "--json"]);
    // Duplicates collapse and the set reads back sorted, so the wire shape
    // cannot depend on the order the flags arrived in.
    let added = fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "render the scene",
            "--id",
            "t-blender",
            "--allowed-model",
            "Blender",
            "--allowed-model",
            "Astra",
            "--allowed-model",
            "Blender",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    assert_eq!(added["allowedModels"], json!(["Astra", "Blender"]));

    let no_model = fixture.run(
        &fixture.main,
        &["claim", "t-blender", "--as", "d1", "--json"],
    );
    assert_eq!(
        refusal_object(&no_model),
        "task t-blender is restricted to models [Astra, Blender]; \
         pass --model with one of them to claim it"
    );
    let wrong = fixture.run(
        &fixture.main,
        &[
            "claim",
            "t-blender",
            "--as",
            "d1",
            "--model",
            "Kimi",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&wrong),
        "task t-blender is restricted to models [Astra, Blender]; model Kimi may not claim it"
    );
    // Case is not folded: there is no master file to fold toward.
    let cased = fixture.run(
        &fixture.main,
        &[
            "claim",
            "t-blender",
            "--as",
            "d1",
            "--model",
            "astra",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&cased),
        "task t-blender is restricted to models [Astra, Blender]; model astra may not claim it"
    );
    let malformed = fixture.run(
        &fixture.main,
        &[
            "claim",
            "t-blender",
            "--as",
            "d1",
            "--model",
            "bad name",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&malformed),
        "model name bad name is not a usable name: \
         it must match ^[A-Za-z0-9][A-Za-z0-9._:/-]{0,63}$"
    );

    let claimed = fixture.ok_json(
        &fixture.main,
        &[
            "claim",
            "t-blender",
            "--as",
            "d1",
            "--model",
            "Astra",
            "--json",
        ],
    );
    assert_eq!(claimed["model"], "Astra");
    let shown = fixture.ok_json(&fixture.main, &["task", "show", "t-blender", "--json"]);
    assert_eq!(shown["claim"]["model"], "Astra");
    assert_eq!(shown["allowedModels"], json!(["Astra", "Blender"]));

    // The declared model rides on the ledger only when it was declared.
    let events = fixture.ok_json(&fixture.main, &["events", "--task", "t-blender", "--json"]);
    let claimed_payload = events
        .as_array()
        .unwrap()
        .iter()
        .find(|event| event["kind"] == "task_claimed")
        .expect("a task_claimed event")["payload"]
        .clone();
    assert_eq!(claimed_payload["model"], "Astra");

    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "open work",
            "--id",
            "t-open",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    fixture.ok_json(&fixture.main, &["claim", "t-open", "--as", "d2", "--json"]);
    let open_events = fixture.ok_json(&fixture.main, &["events", "--task", "t-open", "--json"]);
    let open_payload = open_events
        .as_array()
        .unwrap()
        .iter()
        .find(|event| event["kind"] == "task_claimed")
        .expect("a task_claimed event")["payload"]
        .clone();
    assert!(
        open_payload.get("model").is_none(),
        "an unrestricted claim that declared no model carried one anyway: {open_payload}"
    );

    // Order: driver-only is refused BEFORE the model, and the model BEFORE
    // the assignee. Either pair would otherwise silently swap when the
    // refusals moved.
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "driver work",
            "--id",
            "t-dr",
            "--driver-only",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    let driver_first = fixture.run(&fixture.main, &["claim", "t-dr", "--as", "d3", "--json"]);
    assert_eq!(refusal_object(&driver_first), "task t-dr is driver-only");
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "assigned work",
            "--id",
            "t-as",
            "--assignee",
            "someone-else",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    let model_before_assignee =
        fixture.run(&fixture.main, &["claim", "t-as", "--as", "d3", "--json"]);
    assert_eq!(
        refusal_object(&model_before_assignee),
        "task t-as is restricted to models [Astra]; pass --model with one of them to claim it"
    );
}

/// The scheduler must not offer work the claim path would refuse.
///
/// `--candidates` inspects the same pool `--next` hands out, so a restricted
/// row that is invisible to one must be invisible to the other, and an
/// unrestricted row must be unaffected by `--model` either way.
#[test]
fn claim_next_and_candidates_skip_restricted_rows_unless_the_model_matches() {
    let fixture = Fixture::new("model-candidates");
    fixture.ok_json(&fixture.main, &["init", "--name", "POOL", "--json"]);
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "blender work",
            "--id",
            "t-restricted",
            "--priority",
            "0",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "anyone work",
            "--id",
            "t-free",
            "--priority",
            "1",
            "--as",
            "geoyws",
            "--json",
        ],
    );

    let ids = |args: &[&str]| -> Vec<String> {
        fixture
            .ok_json(&fixture.main, args)
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["id"].as_str().unwrap().to_owned())
            .collect()
    };
    assert_eq!(
        ids(&["claim", "--candidates", "--as", "d1", "--json"]),
        vec!["t-free".to_owned()],
        "a restricted row was offered to a caller that named no model"
    );
    assert_eq!(
        ids(&[
            "claim",
            "--candidates",
            "--as",
            "d1",
            "--model",
            "Kimi",
            "--json"
        ]),
        vec!["t-free".to_owned()],
        "a restricted row was offered to a model outside its list"
    );
    assert_eq!(
        ids(&[
            "claim",
            "--candidates",
            "--as",
            "d1",
            "--model",
            "Astra",
            "--json"
        ]),
        vec!["t-restricted".to_owned(), "t-free".to_owned()],
        "the matching model was not offered the restricted row, or lost the free one"
    );

    // `--next` hands out what `--candidates` showed: the free row for a
    // caller with no model, and the higher-priority restricted row for Astra.
    let without = fixture.ok_json(&fixture.main, &["claim", "--next", "--as", "d1", "--json"]);
    assert_eq!(without["taskID"], "t-free");
    assert!(without["model"].is_null());
    fixture.ok_json(
        &fixture.main,
        &[
            "release",
            "t-free",
            "--lease",
            without["leaseToken"].as_str().unwrap(),
        ],
    );
    let with = fixture.ok_json(
        &fixture.main,
        &[
            "claim", "--next", "--as", "d1", "--model", "Astra", "--json",
        ],
    );
    assert_eq!(with["taskID"], "t-restricted");
    assert_eq!(with["model"], "Astra");
}

/// Accepting a handoff mints a lease, so it answers to the same rule.
#[test]
fn handoff_accept_honours_the_task_model_allow_list() {
    let fixture = Fixture::new("model-handoff");
    fixture.ok_json(&fixture.main, &["init", "--name", "HANDOFF", "--json"]);
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "blender work",
            "--id",
            "t-h",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    let claim = fixture.ok_json(
        &fixture.main,
        &[
            "claim", "t-h", "--as", "outgoing", "--model", "Astra", "--json",
        ],
    );
    let token = claim["leaseToken"].as_str().unwrap().to_owned();
    let handoff = fixture.ok_json(
        &fixture.main,
        &[
            "handoff",
            "create",
            "t-h",
            "--lease",
            &token,
            "--as",
            "outgoing",
            "--summary",
            "half rendered",
            "--intent",
            "finish the render",
            "--next-action",
            "render frames 40-90",
            "--reason",
            "session_end",
            "--json",
        ],
    );
    let handoff_id = handoff["id"].as_str().unwrap().to_owned();

    let refused = fixture.run(
        &fixture.main,
        &[
            "handoff",
            "accept",
            &handoff_id,
            "--as",
            "incoming",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&refused),
        "task t-h is restricted to models [Astra]; pass --model with one of them to claim it"
    );
    let wrong = fixture.run(
        &fixture.main,
        &[
            "handoff",
            "accept",
            &handoff_id,
            "--as",
            "incoming",
            "--model",
            "Kimi",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&wrong),
        "task t-h is restricted to models [Astra]; model Kimi may not claim it"
    );

    let accepted = fixture.ok_json(
        &fixture.main,
        &[
            "handoff",
            "accept",
            &handoff_id,
            "--as",
            "incoming",
            "--model",
            "Astra",
            "--json",
        ],
    );
    assert_eq!(accepted["claim"]["model"], "Astra");
    let events = fixture.ok_json(&fixture.main, &["events", "--task", "t-h", "--json"]);
    let payload = events
        .as_array()
        .unwrap()
        .iter()
        .find(|event| event["kind"] == "handoff_accepted")
        .expect("a handoff_accepted event")["payload"]
        .clone();
    assert_eq!(payload["model"], "Astra");
}

/// The allow-list is replaced wholesale or emptied, never merged.
#[test]
fn task_update_replaces_or_clears_the_allow_list_and_refuses_both_flags() {
    let fixture = Fixture::new("model-update");
    fixture.ok_json(&fixture.main, &["init", "--name", "UPDATE", "--json"]);
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "scene",
            "--id",
            "t-u",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task", "add", "other", "--id", "t-other", "--as", "geoyws", "--json",
        ],
    );

    let both = fixture.run(
        &fixture.main,
        &[
            "task",
            "update",
            "t-u",
            "--allowed-model",
            "Kimi",
            "--clear-allowed-models",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&both),
        "--allowed-model and --clear-allowed-models are mutually exclusive"
    );
    let malformed = fixture.run(
        &fixture.main,
        &[
            "task",
            "update",
            "t-u",
            "--allowed-model",
            "-leading",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&malformed),
        "model name -leading is not a usable name: \
         it must match ^[A-Za-z0-9][A-Za-z0-9._:/-]{0,63}$"
    );
    // The refused update left the row exactly as it was.
    assert_eq!(
        fixture.ok_json(&fixture.main, &["task", "show", "t-u", "--json"])["allowedModels"],
        json!(["Astra"])
    );

    let replaced = fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "update",
            "t-u",
            "--allowed-model",
            "zeta",
            "--allowed-model",
            "Kimi",
            "--allowed-model",
            "zeta",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    assert_eq!(
        replaced["allowedModels"],
        json!(["Kimi", "zeta"]),
        "the update merged instead of replacing, or lost the sort"
    );

    // Server-side filter: only rows whose list holds the name come back.
    let filtered = fixture.ok_json(
        &fixture.main,
        &["task", "list", "--allowed-model", "Kimi", "--json"],
    );
    assert_eq!(
        filtered
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["id"].as_str().unwrap())
            .collect::<Vec<_>>(),
        vec!["t-u"]
    );
    assert!(
        fixture
            .ok_json(
                &fixture.main,
                &["task", "list", "--allowed-model", "Astra", "--json"]
            )
            .as_array()
            .unwrap()
            .is_empty(),
        "the replaced model still filters to the row"
    );

    let cleared = fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "update",
            "t-u",
            "--clear-allowed-models",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    assert_eq!(cleared["allowedModels"], json!([]));
    // And an unrestricted row is claimable by anyone again.
    fixture.ok_json(&fixture.main, &["claim", "t-u", "--as", "anyone", "--json"]);

    let changed = fixture
        .ok_json(&fixture.main, &["events", "--task", "t-u", "--json"])
        .as_array()
        .unwrap()
        .iter()
        .filter(|event| event["kind"] == "task_updated")
        .map(|event| event["payload"]["changed"].clone())
        .collect::<Vec<_>>();
    assert_eq!(
        changed,
        vec![json!(["allowedModels"]), json!(["allowedModels"])],
        "task_updated did not name the field that moved"
    );

    // A no-op replace says nothing moved.
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "update",
            "t-other",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "update",
            "t-other",
            "--allowed-model",
            "Astra",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    let other_changed = fixture
        .ok_json(&fixture.main, &["events", "--task", "t-other", "--json"])
        .as_array()
        .unwrap()
        .iter()
        .filter(|event| event["kind"] == "task_updated")
        .map(|event| event["payload"]["changed"].clone())
        .collect::<Vec<_>>();
    // Newest first, as `events` lists: the second update moved nothing.
    assert_eq!(other_changed, vec![json!([]), json!(["allowedModels"])]);
}

/// A board written before the feature opens, migrates, and reads as
/// unrestricted — with its existing claim's model absent rather than invented.
#[test]
fn a_v29_board_gains_task_models_and_claim_model_and_existing_claims_read_null() {
    let fixture = Fixture::new("model-migration");
    fixture.ok_json(&fixture.main, &["init", "--name", "OLD", "--json"]);
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "older work",
            "--id",
            "t-old",
            "--as",
            "geoyws",
            "--json",
        ],
    );
    fixture.ok_json(&fixture.main, &["claim", "t-old", "--as", "d1", "--json"]);
    let board = board_path_for_project(&fixture, &fixture.main, "OLD");

    {
        let connection = Connection::open(&board).unwrap();
        remove_v30_model_restriction_schema(&connection);
        connection.execute_batch("PRAGMA user_version=29;").unwrap();
        assert_eq!(
            connection
                .query_row(
                    "SELECT count(*) FROM sqlite_schema WHERE type='table' AND name='task_models'",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .unwrap(),
            0,
            "the fixture did not actually reach v29"
        );
    }

    let shown = fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "show",
            "t-old",
            "--db",
            board.to_str().unwrap(),
            "--json",
        ],
    );
    assert_eq!(shown["allowedModels"], json!([]));
    assert!(
        shown["claim"]["model"].is_null(),
        "a pre-migration claim invented a model: {}",
        shown["claim"]
    );

    let connection = Connection::open(&board).unwrap();
    assert_eq!(
        connection
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
            .unwrap(),
        30
    );
    // The table, its index, and the column are all there.
    assert_eq!(
        connection
            .query_row("SELECT count(*) FROM task_models", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        0
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT count(*) FROM sqlite_schema WHERE type='index' \
                 AND name='idx_task_models_model'",
                [],
                |row| row.get::<_, i64>(0)
            )
            .unwrap(),
        1
    );
    // The rebuilt claims table kept the row it copied, its lease included.
    assert_eq!(
        connection
            .query_row(
                "SELECT count(*) FROM task_claims WHERE task_id='t-old' AND model IS NULL",
                [],
                |row| row.get::<_, i64>(0)
            )
            .unwrap(),
        1
    );
    assert_eq!(
        connection
            .query_row(
                "SELECT count(*) FROM sqlite_schema WHERE type='index' \
                 AND name='idx_task_claims_expiry'",
                [],
                |row| row.get::<_, i64>(0)
            )
            .unwrap(),
        1
    );
    drop(connection);

    // And the migrated board restricts exactly as a fresh one does.
    fixture.ok_json(
        &fixture.main,
        &[
            "task",
            "add",
            "new work",
            "--id",
            "t-new",
            "--allowed-model",
            "Astra",
            "--db",
            board.to_str().unwrap(),
            "--as",
            "geoyws",
            "--json",
        ],
    );
    let refused = fixture.run(
        &fixture.main,
        &[
            "claim",
            "t-new",
            "--as",
            "d2",
            "--db",
            board.to_str().unwrap(),
            "--json",
        ],
    );
    assert_eq!(
        refusal_object(&refused),
        "task t-new is restricted to models [Astra]; pass --model with one of them to claim it"
    );
}

/// The MCP tool schemas follow the surface table, so a client reads the
/// allow-list as an array and the claim's model as a string (ADR-010).
#[test]
fn mcp_schema_exposes_allowed_model_array_and_claim_model_string() {
    let fixture = Fixture::new("model-mcp");
    fixture.ok_json(&fixture.main, &["init", "--name", "MCPMODEL", "--json"]);

    let schema = fixture.ok_json(&fixture.main, &["schema", "--json"]);
    let kind = |operation: &str, flag: &str| -> String {
        schema["operations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["name"] == operation)
            .unwrap_or_else(|| panic!("no operation named {operation}"))["flags"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["name"] == flag)
            .unwrap_or_else(|| panic!("{operation} does not accept --{flag}"))["kind"]
            .as_str()
            .unwrap()
            .to_owned()
    };
    assert_eq!(kind("task add", "allowed-model"), "list");
    assert_eq!(kind("task update", "allowed-model"), "list");
    assert_eq!(kind("task update", "clear-allowed-models"), "boolean");
    // Scalar where one name is asked about or declared.
    assert_eq!(kind("task list", "allowed-model"), "value");
    assert_eq!(kind("claim", "model"), "value");
    assert_eq!(kind("handoff accept", "model"), "value");

    let mut session = Session::start(
        Path::new(env!("CARGO_BIN_EXE_kanban")),
        &fixture.main,
        &fixture.data,
    );
    let _ = session.ask(json!({
        "jsonrpc": "2.0", "id": 1, "method": "initialize",
        "params": { "protocolVersion": "2024-11-05", "capabilities": {} }
    }));
    let listed = session.ask(json!({"jsonrpc": "2.0", "id": 2, "method": "tools/list"}));
    let tools = listed["result"]["tools"].as_array().unwrap().clone();
    let tool = |name: &str| -> Value {
        tools
            .iter()
            .find(|tool| tool["name"] == name)
            .unwrap_or_else(|| panic!("no tool named {name}: {listed}"))
            .clone()
    };
    let add = tool("task_add");
    assert_eq!(
        add["inputSchema"]["properties"]["allowed-model"]["type"],
        "array"
    );
    assert_eq!(
        add["inputSchema"]["properties"]["allowed-model"]["items"]["type"],
        "string"
    );
    let update = tool("task_update");
    assert_eq!(
        update["inputSchema"]["properties"]["allowed-model"]["type"],
        "array"
    );
    assert_eq!(
        update["inputSchema"]["properties"]["clear-allowed-models"]["type"],
        "boolean"
    );
    assert_eq!(
        tool("task_list")["inputSchema"]["properties"]["allowed-model"]["type"],
        "string"
    );
    assert_eq!(
        tool("claim")["inputSchema"]["properties"]["model"]["type"],
        "string"
    );
    assert_eq!(
        tool("handoff_accept")["inputSchema"]["properties"]["model"]["type"],
        "string"
    );

    // And the tool actually restricts through the MCP path, not only the CLI.
    let called = session.ask(json!({
        "jsonrpc": "2.0", "id": 3, "method": "tools/call",
        "params": { "name": "task_add", "arguments": {
            "title": "mcp scene", "id": "t-mcp", "as": "geoyws",
            "allowed-model": ["Astra", "Blender"]
        }}
    }));
    assert_eq!(
        called["result"]["isError"],
        json!(false),
        "task_add through MCP failed: {called}"
    );
    let refused = session.ask(json!({
        "jsonrpc": "2.0", "id": 4, "method": "tools/call",
        "params": { "name": "claim", "arguments": { "id": "t-mcp", "as": "d1" }}
    }));
    let text = refused["result"]["content"][0]["text"].as_str().unwrap();
    assert!(
        text.contains(
            "task t-mcp is restricted to models [Astra, Blender]; \
             pass --model with one of them to claim it"
        ),
        "{refused}"
    );
}
